            db.setTransactionSuccessful()
        } catch (e: Exception) {
            e.printStackTrace()
        } finally {
            db.endTransaction()
        }
    }

    private fun ensureColumnsExist(db: SupportSQLiteDatabase) {
        val catCols = getTableColumns(db, "dua_category")
        if (!catCols.contains("bnTitle")) {
            db.execSQL("ALTER TABLE dua_category ADD COLUMN bnTitle TEXT")
        }

        val itemCols = getTableColumns(db, "dua_item")
        if (!itemCols.contains("bnTranslation")) {
            db.execSQL("ALTER TABLE dua_item ADD COLUMN bnTranslation TEXT")
        }
        if (!itemCols.contains("bnTransliteration")) {
            db.execSQL("ALTER TABLE dua_item ADD COLUMN bnTransliteration TEXT")
        }
        if (!itemCols.contains("bnReference")) {
            db.execSQL("ALTER TABLE dua_item ADD COLUMN bnReference TEXT")
        }
    }

    private fun getTableColumns(db: SupportSQLiteDatabase, tableName: String): Set<String> {
        val columns = mutableSetOf<String>()
        val cursor = db.query("PRAGMA table_info(" + tableName + ")")
        cursor.use {
            val nameIndex = cursor.getColumnIndex("name")
            while (cursor.moveToNext()) {
                if (nameIndex != -1) {
                    columns.add(cursor.getString(nameIndex))
                }
            }
        }
        return columns
    }

