        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে। হে আল্লাহ! আমি আপনার নিকট অপবিত্র নর জিন্ ও নারী জিন্ থেকে আশ্রয় চাই" + "', bnTransliteration = '" + "বিসমিল্লাহি আল্লা-হুম্মা ইন্নী আ‘ঊযু বিকা মিনাল খুব্‌সি ওয়াল খাবা-ইসি" + "', bnReference = '" + "বুখারী ১/৪৫, নং ১৪২; মুসলিম ১/২৮৩, নং ৩৭৫। শুরুতে অতিরিক্ত ‘বিসমিল্লাহ্‌’ উদ্ধৃত করেছেন সা‘ঈদ ইবন মানসূর। দেখুন, ফাতহুল বারী, ১/২৪৪" + "' WHERE id = 10")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি আপনার কাছে ক্ষমাপ্রার্থী।" + "', bnTransliteration = '" + "গুফরা-নাকা" + "', bnReference = '" + "হাদীসটি নাসাঈ ব্যতীত সকল সুনান গ্রন্থকারই উদ্ধৃত করেছেন; তবে নাসাঈ তার ‘আমালুল ইয়াওমি ওয়াললাইলাহ’ গ্রন্থে (নং ৭৯) তা উদ্ধৃত করেছেন। আবূ দাউদ, নং ৩০; তিরমিযী, নং ৭; ইবন মাজাহ্‌, নং ৩০০। আর শাইখ আলবানী সহীহ সুনান আবি দাউদে ১/১৯ একে সহীহ বলেছেন।" + "' WHERE id = 11")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে" + "', bnTransliteration = '" + "বিস্‌মিল্লা-হ্" + "', bnReference = '" + "আবূ দাউদ, নং ১০১; ইবন মাজাহ্‌, নং ৩৯৭; আহমাদ নং ৯৪১৮। আরও দেখুন, ইরওয়াউল গালীল ১/১২২  [১] হাদিসটি কয়েকটি দূর্বল সনদে বর্ণিত; ভিন্ন ভিন্ন যয়ীফ সনদের সমন্বয়ে গ্রহণযোগ্যতা পেয়েছে। তিরমিযী (আবওয়াবুত তাহারাহ ,২০- বাব ফিত তাসমিয়াতি...) ১/৩৭-৩৯ (ভারতীয় ১/১৩); যাইলায়ী, নাসবুর রাইয়াহ ১/৩-৬, ইবনু হাজার, তালখীসুল হাবীর ১/৭২, আলবানী, সহীহুল জামি ২/১২৫৬, নং ৭৫৭০; রাহে বেলায়াত - যিকর নং ৩৬" + "' WHERE id = 12")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি সাক্ষ্য দিচ্ছি যে, একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। আমি আরও সাক্ষ্য দিচ্ছি যে, মুহাম্মাদ তাঁর বান্দা ও রাসূল" + "', bnTransliteration = '" + "আশ্‌হাদু আল্লা-ইলাহা ইল্লাল্লাহু ওয়াহ্‌দাহু লা- শারীকা লাহূ ওয়া আশহাদু আন্না মুহাম্মাদান ‘আব্দুহূ ওয়া রাসূলুহূ" + "', bnReference = '" + "মুসলিম ১/২০৯, নং ২৩৪" + "' WHERE id = 13")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমাকে তাওবাকারীদের অন্তর্ভুক্ত করুন এবং পবিত্রতা অর্জনকারীদেরও অন্তর্ভুক্ত করুন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাজ‘আলনী মিনাত্ তাওয়াবীনা ওয়াজ‘আলনী মিনাল মুতাতাহ্‌হিরীন" + "', bnReference = '" + "তিরিমিযী-১/৭৮, নং ৫৫। আরও দেখুন, সহীহুত তিরমিযী, ১/১৮।" + "' WHERE id = 14")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনার প্রশংসাসহ পবিত্রতা ও মহিমা ঘোষণা করছি। আমি সাক্ষ্য দেই যে, আপনি ছাড়া কোন হক্ব ইলাহ নেই, আমি আপনার কাছে ক্ষমা প্রার্থনা করছি এবং আপনার নিকট তওবা করছি" + "', bnTransliteration = '" + "সুবহানাকা আল্লা-হুম্মা ওয়া বিহামদিকা আশহাদু আল লা-ইলাহা ইল্লা আন্তা আস্তাগফিরুকা ওয়াআতূবু ইলাইকা" + "', bnReference = '" + "নাসাঈ, আমালুল ইয়াওমি ওয়াল লাইলাহ, পৃ. ১৭৩ আরও দেখুন, ইরওয়াউল গালীল, ১/১৩৫, ৩/৯৪" + "' WHERE id = 15")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে (বের হচ্ছি)। আল্লাহর উপর ভরসা করলাম। আর আল্লাহর সাহায্য ছাড়া (পাপ কাজ থেকে দূরে থাকার) কোনো উপায় এবং (সৎকাজ করার) কোনো শক্তি কারো নেই [১]" + "', bnTransliteration = '" + "বিসমিল্লাহি, তাওয়াককালতু ‘আলাল্লা-হি, ওয়ালা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ" + "', bnReference = '" + "[১] আবূ দাউদ ৪/৩২৫, নং ৫০৯৫; তিরমিযী ৫/৪৯০, ৩৪২৬। আরও দেখুন, সহীহুত তিরমিযী, ৩/১৫১ [২] তিরমিযী (৩৯-কিতাবুদ্দাওয়াত,৩৪-বাব ইয়াকুলু ইযা খরাজা) ৫/৪৫৬, নং ৩৪২৬ (ভা ২/১৮০-১৮১)।" + "' WHERE id = 16")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার নিকট আশ্রয় চাই যেন নিজেকে বা অন্যকে পথভ্রষ্ট না করি, অথবা অন্যের দ্বারা পথভ্রষ্ট না হই; আমার নিজের বা অন্যের পদস্খলন না করি, অথবা আমায় যেন পদস্খলন করানো না হয়; আমি যেন নিজের বা অন্যের উপর যুলম না করি অথবা আমার প্রতি যুলম না করা হয়; আমি যেন নিজে মুর্খতা না করি, অথবা আমার উপর মূর্খতা করা না হয়।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী আ‘ঊযু বিকা আন আদ্বিল্লা, আও উদ্বাল্লা, আও আযিল্লা, আও উযাল্লা, আও আযলিমা, আও উযলামা, আও আজহালা, আও ইয়ুজহালা ‘আলাইয়্যা" + "', bnReference = '" + "সুনান গ্রন্থকারগণ: আবূ দাউদ, নং ৫০৯৪; তিরমিযী, নং ৩৪২৭; নাসাঈ, নং ৫৫০১; ইবন মাজাহ, নং ৩৮৮৪ আরও দেখুন, সহীহুত তিরমিযী ৩/১৫২; সহীহ ইবন মাজাহ্‌ ২/৩৩৬।" + "' WHERE id = 17")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে আমরা প্রবেশ করলাম, আল্লাহ্‌র নামেই আমরা বের হলাম এবং আমাদের রব আল্লাহ্‌র উপরই আমরা ভরসা করলাম" + "', bnTransliteration = '" + "বিসমিল্লাহি ওয়ালাজনা, ওয়াবিস্‌মিল্লাহি খারাজনা, ওয়া ‘আলাল্লাহি রাব্বিনা তাওয়াক্কালনা" + "', bnReference = '" + "[১] আবূ দাউদ ৪/৩২৫, ৫০৯৬। আর আল্লামা ইবন বায রহ. তার তুহফাতুল আখইয়ার গ্রন্থে পৃ. ২৮ এটার সনদকে হাসান বলেছেন।  [২] মুসলিম, নং ২০১৮।" + "' WHERE id = 18")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমার অন্তরে নূর (বা আলো) দান করুন, আমার যবানে নূর দান করুন, আমার শ্রবণশক্তিতে নূর দান করুন, আমার দর্শনশক্তিতে নূর দান করুন, আমার উপরে নূর দান করুন, আমার নীচে নূর দান করুন, আমার ডানে নূর দান করুন, আমার বামে নূর দান করুন, আমার সামনে নূর দান করুন, আমার পেছনে নূর দান করুন, আমার আত্মায় নূর দান করুন, আমার জন্য নূরকে বড় করে দিন, আমার জন্য নূর বাড়িয়ে দিন, আমার জন্য নূর নির্ধারণ করুন, আমাকে আলোকময় করুন। হে আল্লাহ! আমাকে নূর দান করুন, আমার পেশীতে নূর প্রদান করুন, আমার গোশ্‌তে নূর দান করুন, আমার রক্তে নূর দান করুন, আমার চুলে নূর দান করুন ও আমার চামড়ায় নূর দান করুন। [১] হে আল্লাহ! আমার জন্য আমার কবরে নূর দিন, আমার হাড়সমূহেও নূর দিন [২] আমাকে নূরে বৃদ্ধি করে দিন, আমাকে নূরে বৃদ্ধি করে দিন, আমাকে নূরে বৃদ্ধি করে দিন [৩] আমাকে নূরের উপর নূর দান করুন [৪]" + "', bnTransliteration = '" + "আল্লা-হুম্মাজ‘আল ফী ক্বালবী নূরান, ওয়া ফী লিসানী নূরান, ওয়া ফী সাম্‘য়ী নূরান, ওয়া ফী বাসারী নূরান, ওয়া মিন ফাওকী নূরান, ওয়া মিন তাহ্‌তী নূরান, ওয়া ‘আন ইয়ামীনী নূরান, ওয়া ‘আন শিমালী নূরান, ওয়া মিন আমামী নূরান, ওয়া মিন খলফী নূরান, ওয়াজ‘আল ফী নাফ্‌সী নূরান, ওয়া আ‘যিম লী নূরান, ওয়া ‘আয্‌যিম লী নূরান, ওয়াজ‘আল্ লী নূরান, ওয়াজ‘আলনী নূরান; আল্লা-হুম্মা আ‘তিনী নূরান, ওয়াজ‘আল ফী ‘আসাবী নূরান, ওয়া ফী লাহ্‌মী নূরান, ওয়া ফী দামী নূরান, ওয়া ফী শা‘রী নূরান, ওয়া ফী বাশারী নূরান। আল্লা-হুম্মাজ‘আল লী নূরান ফী কাবরী... ওয়া নূরান ফী ‘ইযামী ওয়া যিদ্‌নী নূরান, ওয়া যিদনী নূরান, ওয়া যিদনী নূরান ওয়া হাবলী নূরান ‘আলা নুর" + "', bnReference = '" + "[১] এ শব্দগুলোর জন্য দেখুন, বুখারী, (ফাতহুল বারীসহ) ১১/১১৬, নং ৬৩১৬; মুসলিম ১/৫২৬, ৫২৯, ৫৩০, নং ৭৬৩ [২] তিরমিযী ৫/৪৮৩, নং ৩৪১৯।  [৩] ইমাম বুখারী, আল-আদাবুল মুফরাদ, নং ৬৯৫; পৃ. ২৫৮; আর আলবানী সেটার সনদকে সহীহ আদাবিল মুফরাদে সহীহ বলেছেন, নং ৫৩৬।  [৪] হাফেয ইবন হাজার এটাকে তার ফতহুল বারীতে উল্লেখ করেছেন এবং ইবন আবী আসেমের ‘কিতাবুদ দো‘আ’ এর দিকে সম্পর্কিত করেছেন। দেখুন ফাতহুল বারী, ১১/১১৮। আরও বলেছেন, বিভিন্ন বর্ণনা থেকে মোট ২৫ (পঁচিশটি) বিষয় পাওয়া গেল।" + "' WHERE id = 19")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি মহান আল্লাহ্‌র কাছে তাঁর সম্মানিত চেহারা ও প্রাচীন ক্ষমতার ওসীলায় বিতাড়িত শয়তান থেকে আশ্রয় প্রার্থনা করছি। [২] আল্লাহ্‌র নামে (প্রবেশ করছি) [৩] সালাত ও সালাম আল্লাহ্‌র রাসূলের উপর। [৪] হে আল্লাহ! আপনি আমার জন্য আপনার রহমতের দরজাসমূহ খুলে দিন। [৫]" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হিল ‘আযীম, ওয়া বিওয়াজহিহিল কারীম, ওয়াসুলতা-নিহিল ক্বদীম, মিনাশ শাইত্বা-নির রাজীম। বিসমিল্লা-হি ওয়াসসালাতু ওয়াসসালা-মু ‘আলা রাসূলিল্লা-হি আল্লা-হুম্মাফ্‌তাহ লী আবওয়া-বা রাহ্‌মাতিকা" + "', bnReference = '" + "[১] হাদীসটি উদ্ধৃত করেছেন, হাকিম ১/২১৮; এবং একে মুসলিমের শর্ত অনুযায়ী সহীহ বলেছেন, আর ইমাম যাহাবী সেটার সমর্থন করেছেন। আরও উদ্ধৃত করেছেন বাইহাকী, ২/৪৪২; আর শাইখ আলবানী তার সিলসিলাতুল আহাদীসিস সহীহা গ্রন্থে এটাকে হাসান বলেছেন, ৫/৬২৪; নং ২৪৭৮।  [২] আবূ দাউদ, নং ৪৬৬; আরও দেখুন, সহীহুল জামে‘ ৪৫৯১ [৩] ইবনুসসুন্নি কর্তৃক উদ্ধৃত, নং ৮। আর শাইখ আলবানী তার আস-সামারুল মুস্তাতাব গ্রন্থে একে হাসান বলেছেন, পৃ. ৬০৭।  [৪] আবূ দাউদ ১/১২৬; নং ৪৬৫; আরও দেখুন, সহীহুল জামে‘ ১/৫২৮।  [৫] মুসলিম ১/৪৯৪, নং ৭১৩; আর সুনান ইবন মাজায় ফাতিমা রাদিয়াল্লাহু আনহার হাদীসে এসেছে, “হে আল্লাহ, আমার গুনাহ ক্ষমা করে দিন এবং আমার জন্য আপনার রহমতের দ্বারসমূহ অবারিত করে দিন”। আর শাইখ আলবানী অন্যান্য শাহেদ বা সম অর্থের বর্ণনার কারণে একে সহীহ বলেছেন। দেখুন, সহীহ ইবন মাজাহ্ ১/১২৮-১২৯। [৬] আবু দাঊদ(কিতাবুস সালাত,বাব ফীমা ইয়াকুলুর রজুলু ইনদা দুখুলিহিল মাসজিদ) ১/১২৪,নং ৪৬৬ (ভা ১/৬৭); আলবানী,সহীহুল জামিয়িস সাগীর ২/৮৬০,নং ৪৭১৫।" + "' WHERE id = 20")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে (বের হচ্ছি)। আল্লাহ্‌র রাসুলের উপর শান্তি বর্ষিত হোক। হে আল্লাহ! আপনি আমার গুনাসমূহ মাফ করে দিন এবং আমার জন্য আপনার দয়ার দরজাগুলো খুলে দিন। হে আল্লাহ, আমাকে বিতাড়িত শয়তান থেকে হেফাযত করুন [২]" + "', bnTransliteration = '" + "বিস্‌মিল্লা-হি ওয়াস্‌সালা-তু ওয়াস্‌সালা-মু ‘আলা রাসূলিল্লাহ, আল্লা-হুম্মা ইন্নী আসআলুকা মিন ফাদ্বলিকা, আল্লা-হুম্মা আ‘সিমনি মিনাশ শাইত্বানির রাজীম।" + "', bnReference = '" + "[১] আল-হাকিম, ১/২১৮; বাইহাকী, ২/৪৪২, আর শাইখ আলবানী তার সিলসিলাতুস সহীহায় একে হাসান হাদীস বলেছেন, ৫/৬২৪, নং ২৪৭৮। আর সেটার তাখরীজ পূর্বে গত হয়েছে।  [২] মসজিদে প্রবেশের দো‘আয় পূর্বে বর্ণিত হাদীসের রেওয়ায়েতসমূহের তাখরীজ দেখুন, (২০ নং) আর “হে আল্লাহ, আমাকে বিতাড়িত শয়তান থেকে হেফাযত করুন” এ বাড়তি অংশের তাখরীজ দেখুন, ইবন মাজাহ্‌ ১/১২৯।" + "' WHERE id = 21")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নামাযের দিকে আসো, কল্যানের দিকে আসো আল্লাহর সাহায্য ছাড়া (পাপ কাজ থেকে দূরে থাকার) কোনো উপায় এবং (সৎকাজ করার) কোনো শক্তি কারো নেই। [১] আমি সাক্ষ্য দিচ্ছি যে, একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। আমি আরো সাক্ষ্য দিচ্ছি যে, মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাঁর বান্দাহ ও রাসূল। আমি আল্লাহকে রব্ব, মুহাম্মাদ (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) কে রাসূল এবং ইসলামকে দীন হিসেবে গ্রহণ করে সন্তুষ্ট। হে আল্লাহ! এই পরিপূর্ণ আহ্বান এবং প্রতিষ্ঠিত সালাতের রব্ব! মুহাম্মাদ (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) কে ওসীলা তথা জান্নাতের একটি স্তর এবং ফযীলত তথা সকল সৃষ্টির উপর অতিরিক্ত মর্যাদা দান করুন। আর তাঁকে মাকামে মাহমূদে (প্রশংসিত স্থানে) পৌঁছে দিন, যার প্রতিশ্রুতি আপনি তাঁকে দিয়েছেন। (নিশ্চয় আপনি প্রতিশ্রুতি ভঙ্গ করেন না।) [৩]" + "', bnTransliteration = '" + "হাইয়্যা ‘আলাস্‌সালাহ, হাইয়্যা ‘আলাল ফালাহ’ লা-হাওলা ওয়ালা ক্বুওয়াতা ইল্লা বিল্লা-হ ওয়া আনা আশ্‌হাদু আল্লা ইলা-হা ইল্লাল্লা-হু ওয়াহ্‌দাহু লা শারীকা লাহু ওয়া আন্না মুহাম্মাদান ‘আবদুহূ ওয়া রাসূলুহু, রাদীতু বিল্লা-হি রব্‌বান, ওয়া বিমুহাম্মাদিন রাসূলান, ওয়া বিলইসলা-মি দীনান আল্লা-হুম্মা রববা হা-যিহিদ্ দা‘ওয়াতিত্ তা-ম্মাতি ওয়াস সালা-তিল ক্বা-’ইমাতি আ-তি মুহাম্মাদানিল ওয়াসীলাতা ওয়াল ফাদীলাতা ওয়াব্‘আছহু মাক্বা-মাম মাহমূদানিল্লাযী ওয়া‘আদতাহ, (ইন্নাকা লা তুখলিফুল মী‘আদ)" + "', bnReference = '" + "[১] বুখারী, ১/১৫২, নং ৬১১, ৬১৩; মুসলিম, ১/২৮৮, নং ৩৮৩ [২] মুসলিম ৩/১৫৫৭, নং ১৯৬৭; বায়হাকী ৯/২৮৭, দু ব্রাকেটের মাঝখানের অংশ বাইহাকী থেকে, ৯/২৮৭, ইত্যাদি। তবে সর্বশেষ বাক্যটি ইমাম মুসলিমের বর্ণনা থেকে অর্থ হিসেবে গৃহীত।  [৩] আহমাদ ৩/৪১৯, নং ১৫৪৬১, সহীহ সনদে। আর ইবনুস সুন্নী, নং ৬৩৭; আরনাঊত তার ত্বাহাভীয়ার তাখরীজে এর সনদকে বিশুদ্ধ বলেছেন, পৃ.১৩৩ আরও দেখুন, মাজমা‘উয যাওয়ায়েদ ১০/১২৭।  [৪] মুসলিম (৪-কিতাবুস সালাত,৭-বাব ইসতিহবাবিল কাওলি মিসল...) ১/২৮৮, নং ৩৮৪(ভা ১/১৬৬) [৫] বুখারী(১৪-কিতাবুল আযান, ৮-বাবুদ দাআ ইনদান নিদা) ১/২২২ নং ৫৮৯ (ভারতীয় ১/৮৬)। [৬] সহীহ ইবন হিব্বান ৪/৫৫৩, মুসতাদরাক হাকিম ১/৩২১; আলবানী সহীহুত তারগীব ১/১৭৭।" + "' WHERE id = 22")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নামাযের দিকে আসো, কল্যানের দিকে আসো আল্লাহর সাহায্য ছাড়া (পাপ কাজ থেকে দূরে থাকার) কোনো উপায় এবং (সৎকাজ করার) কোনো শক্তি কারো নেই। [১] আমি সাক্ষ্য দিচ্ছি যে, একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। আমি আরো সাক্ষ্য দিচ্ছি যে, মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাঁর বান্দাহ ও রাসূল। আমি আল্লাহকে রব্ব, মুহাম্মাদ (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) কে রাসূল এবং ইসলামকে দীন হিসেবে গ্রহণ করে সন্তুষ্ট। হে আল্লাহ! এই পরিপূর্ণ আহ্বান এবং প্রতিষ্ঠিত সালাতের রব্ব! মুহাম্মাদ (সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম) কে ওসীলা তথা জান্নাতের একটি স্তর এবং ফযীলত তথা সকল সৃষ্টির উপর অতিরিক্ত মর্যাদা দান করুন। আর তাঁকে মাকামে মাহমূদে (প্রশংসিত স্থানে) পৌঁছে দিন, যার প্রতিশ্রুতি আপনি তাঁকে দিয়েছেন। (নিশ্চয় আপনি প্রতিশ্রুতি ভঙ্গ করেন না।) [৩]" + "', bnTransliteration = '" + "হাইয়্যা ‘আলাস্‌সালাহ, হাইয়্যা ‘আলাল ফালাহ’ লা-হাওলা ওয়ালা ক্বুওয়াতা ইল্লা বিল্লা-হ ওয়া আনা আশ্‌হাদু আল্লা ইলা-হা ইল্লাল্লা-হু ওয়াহ্‌দাহু লা শারীকা লাহু ওয়া আন্না মুহাম্মাদান ‘আবদুহূ ওয়া রাসূলুহু, রাদীতু বিল্লা-হি রব্‌বান, ওয়া বিমুহাম্মাদিন রাসূলান, ওয়া বিলইসলা-মি দীনান আল্লা-হুম্মা রববা হা-যিহিদ্ দা‘ওয়াতিত্ তা-ম্মাতি ওয়াস সালা-তিল ক্বা-’ইমাতি আ-তি মুহাম্মাদানিল ওয়াসীলাতা ওয়াল ফাদীলাতা ওয়াব্‘আছহু মাক্বা-মাম মাহমূদানিল্লাযী ওয়া‘আদতাহ, (ইন্নাকা লা তুখলিফুল মী‘আদ)" + "', bnReference = '" + "[১] বুখারী, ১/১৫২, নং ৬১১, ৬১৩; মুসলিম, ১/২৮৮, নং ৩৮৩ [২] মুসলিম ৩/১৫৫৭, নং ১৯৬৭; বায়হাকী ৯/২৮৭, দু ব্রাকেটের মাঝখানের অংশ বাইহাকী থেকে, ৯/২৮৭, ইত্যাদি। তবে সর্বশেষ বাক্যটি ইমাম মুসলিমের বর্ণনা থেকে অর্থ হিসেবে গৃহীত।  [৩] আহমাদ ৩/৪১৯, নং ১৫৪৬১, সহীহ সনদে। আর ইবনুস সুন্নী, নং ৬৩৭; আরনাঊত তার ত্বাহাভীয়ার তাখরীজে এর সনদকে বিশুদ্ধ বলেছেন, পৃ.১৩৩ আরও দেখুন, মাজমা‘উয যাওয়ায়েদ ১০/১২৭।  [৪] মুসলিম (৪-কিতাবুস সালাত,৭-বাব ইসতিহবাবিল কাওলি মিসল...) ১/২৮৮, নং ৩৮৪(ভা ১/১৬৬) [৫] বুখারী(১৪-কিতাবুল আযান, ৮-বাবুদ দাআ ইনদান নিদা) ১/২২২ নং ৫৮৯ (ভারতীয় ১/৮৬)। [৬] সহীহ ইবন হিব্বান ৪/৫৫৩, মুসতাদরাক হাকিম ১/৩২১; আলবানী সহীহুত তারগীব ১/১৭৭।" + "' WHERE id = 23")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "অতঃপর আযানের পর নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর উপর দরূদ পাঠ করবে।" + "', bnTransliteration = '" + "সাল্লাল্লাহু ‘আলাইহি ওয়া সাল্লাম" + "', bnReference = '" + "মুসলিম ১/২৮৮, নং ৩৮৪" + "' WHERE id = 24")
