        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমার এবং আমার গুনাহসমূহের মধ্যে এমন দূরত্ব সৃষ্টি করুন যেরূপ দূরত্ব সৃষ্টি করেছেন পূর্ব ও পশ্চিমের মধ্যে। হে আল্লাহ! আপনি আমাকে আমার গুনাহসমূহ থেকে এমন পরিষ্কার করে দিন, যেমন সাদা কাপড় ময়লা থেকে পরিষ্কার করা হয়। হে আল্লাহ! আপনি আমাকে আমার পাপসমূহ থেকে বরফ, পানি ও মেঘের শিলাখণ্ড দ্বারা ধৌত করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা বা-‘ইদ বাইনী ওয়া বাইনা খাত্বা-ইয়া-ইয়া কামা বা-‘আদতা বাইনাল মাশরিক্বি ওয়াল মাগরিব। আল্লা-হুম্মা নাক্বক্বিনী মিন খাত্বা-ইয়া-ইয়া কামা ইয়ুনাক্কাস্ ছাওবুল আবইয়াদু মিনাদ দানাসি। আল্লা-হুম্মাগসিলনী মিন খাত্বা-ইয়া-ইয়া বিল মা-’ই ওয়াস সালজি ওয়াল বারাদ" + "', bnReference = '" + "বুখারী ১/১৮১, নং ৭৪৪; মুসলিম ১/৪১৯, নং ৫৯৮।" + "' WHERE id = 27")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনার প্রশংসাসহ আপনার পবিত্রতা ও মহিমা ঘোষণা করছি, আপনার নাম বড়ই বরকতময়, আপনার প্রতিপত্তি অতি উচ্চ। আর আপনি ব্যতীত অন্য কোনো হক্ব ইলাহ্‌ নেই।" + "', bnTransliteration = '" + "সুবহা-নাকাল্লা-হুম্মা ওয়া বিহামদিকা ওয়া তাবা-রাকাসমুকা ওয়া তা‘আ-লা জাদ্দুকা ওয়া লা- ইলা-হা গাইরুকা" + "', bnReference = '" + "মুসলিম, নং ৩৯৯; আর সুনান গ্রন্থকার চারজন। আবু দাউদ, নং ৭৭৫; তিরমিযী, নং ২৪৩; ইবন মাজাহ্‌, নং ৮০৬; নাসাঈ, নং ৮৯৯। আরও দেখুন, সহীহুত তিরমিযী, ১/৭৭; সহীহ ইবন মাজাহ্ ১/১৩৫।" + "' WHERE id = 28")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "যিনি আসমানসমূহ ও যমীন সৃষ্টি করেছেন আমি একনিষ্টভাবে আমার মুখমণ্ডল তাঁর দিকেই ফিরালাম, আর আমি মুশরিকদের অন্তর্ভুক্ত নই। নিশ্চয় আমার সালাত, আমার কুরবানী বা যাবতীয় ইবাদাত, আমার জীবন ও আমার মরণ সৃষ্টিকুলের রব্ব আল্লাহ্‌র জন্য। তাঁর কোনো শরীক নেই। আর আমি এরই আদেশ প্রাপ্ত হয়েছি এবং আমি মুসলিমদের অন্তর্ভুক্ত। হে আল্লাহ! আপনিই অধিপতি, আপনি ব্যতীত আর কোনো হক্ব ইলাহ নেই। আপনি আমার রব্ব, আমি আপনার বান্দা। আমি আমার নিজের প্রতি অন্যায় করেছি এবং আমি আমার পাপসমূহ স্বীকার করছি। সুতরাং আপনি আমার সমুদয় গুনাহ মাফ করে দিন। নিশ্চয় আপনি ছাড়া আর কেউ গুনাহসমূহ মাফ করতে পারে না। আর আপনি আমাকে সর্বোত্তম চরিত্রের পথে পরিচালিত করুন, আপনি ছাড়া আর কেউ উত্তম চরিত্রের পথে পরিচালিত করতে পারে না। আর আপনি আমার থেকে আমার খারাপ চরিত্রগুলো দূরীভূত করুন, আপনি ব্যতীত আর কেউ সে খারাপ চরিত্রগুলো অপসারিত করতে পারে না। আমি আপনার হুকুম মানার জন্য সদা-সর্বদা হাজির, সকল কল্যাণই আপনার দু’ হাতে নিহিত। অকল্যাণ আপনার দিকে নয় (অর্থাৎ মন্দকে আপনার দিকে সম্পৃক্ত করা উচিত নয়, অথবা মন্দ দ্বারা আপনার নিকটবর্তী হওয়া যায় না, বা মন্দ আপনার দিকে উঠে না)। আমি আপনার দ্বারাই (প্রতিষ্ঠিত আছি, সহযোগিতা পেয়ে থাকি) এবং আপনার দিকেই (আমার সকল প্রবণতা, বা আমার প্রত্যাবর্তন)। আপনি বরকতময় এবং আপনি সুঊচ্চ। আমি আপনার নিকট ক্ষমা চাই এবং আপনার কাছে তাওবাহ্‌ করছি।" + "', bnTransliteration = '" + "ওয়াজ্জাহ্‌তু ওয়াজহিয়া লিল্লাযী ফাত্বারাস্ সামা-ওয়াতি ওয়াল আরদ্বা হানীফাও ওয়ামা আনা মিনাল মুশরিকীন। ইন্না সালা-তী, ওয়া নুসুকী ওয়া মাহইয়া-ইয়া ওয়া মামা-তী লিল্লা-হি রাব্বিল ‘আ-লামীন। লা শারীকা লাহু ওয়াবিযা-লিকা উমিরতু ওয়া আনা মিনাল মুসলিমীন। আল্লা-হুম্মা আনতাল মালিকু লা ইলা-হা ইল্লা আনতা, আনতা রব্বী ওয়া আনা ‘আবদুকা। যালামতু নাফসী ওয়া‘তারাফতু বিযাম্বী। ফাগফির লী যুনূবী জামী‘আন ইন্নাহু লা- ইয়াগফিরুয্ যুনূবা ইল্লা আনতা। ওয়াহদিনী লিআহসানিল আখলা-ক্বি, লা ইয়াহ্‌দী লিআহ্‌সানিহা ইল্লা আনতা। ওয়াসরিফ ‘আন্নী সায়্যিআহা লা ইয়াসরিফু সায়্যিআহা ইল্লা আনতা। লাববাইকা ওয়া সা‘দাইকা ওয়াল-খাইরু কুল্লুহু বিয়াদাইকা, ওয়াশশাররু লাইসা ইলাইকা। আনা বিকা ওয়া ইলাইকা, তাবা-রাক্তা ওয়া তা‘আ-লাইতা। আসতাগফিরুকা ওয়া আতূবু ইলাইকা" + "', bnReference = '" + "মুসলিম ১/৫৩৪, নং ৭৭১" + "' WHERE id = 29")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! জিবরাঈল, মীকাঈল ও ইসরাফীলের রব্ব, আসমান ও যমীনের স্রষ্টা, গায়েব ও প্রকাশ্য সব কিছুর জ্ঞানী, আপনার বান্দাগণ যেসব বিষয়ে মতভেদে লিপ্ত আপনিই তার মীমাংসা করে দিবেন। যেসব বিষয়ে মতভেদ হয়েছে তন্মধ্যে আপনি আপনার অনুমতিক্রমে আমাকে যা সত্য সেদিকে পরিচালিত করুন। নিশ্চয় আপনি যাকে ইচ্ছা সরল পথ প্রদর্শন করেন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা রববা জিব্রাঈলা ওয়া মীকাঈলা ওয়া ইস্রা-ফীলা ফা-তিরাস্ সামা-ওয়া-তি ওয়াল আরদি ‘আ-লিমাল গাইবি ওয়াশশাহা-দাতি। আনতা তাহকুমু বাইনা ইবা-দিকা ফীমা কা-নূ ফীহি ইয়াখতালিফূন। ইহদিনী লিমাখতুলিফা ফীহি মিনাল হাককি বিইযনিকা ইন্নাকা তাহ্‌দী তাশা-উ ইলা- সিরা-তিম মুস্তাকীম" + "', bnReference = '" + "মুসলিম ১/৫৩৪, নং ৭৭০।" + "' WHERE id = 30")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ সবচেয়ে বড় অতীব বড়, আল্লাহ সবচেয়ে বড় অতীব বড়, আল্লাহ সবচেয়ে বড় অতীব বড়। আর আল্লাহ্‌র জন্যই অনেক ও অজস্র প্রশংসা, আল্লাহ্‌র জন্যই অনেক ও অজস্র প্রশংসা, আল্লাহ্‌র জন্যই অনেক ও অজস্র প্রশংসা। সকালে ও বিকালে আল্লাহ্‌র পবিত্রতা ও মহিমা ঘোষণা করছি আমি শয়তান থেকে আল্লাহ্‌র নিকট আশ্রয় চাই। আশ্রয় চাই তার ফুঁ তথা দম্ভ-অহংকার থেকে, তার থুতু তথা কবিতা থেকে ও তার চাপ তথা পাগলামি থেকে" + "', bnTransliteration = '" + "আল্লা-হু আকবার কাবীরান, আল্লা-হু আকবার কাবীরান, আল্লা-হু আকবার কাবীরান, ওয়ালহামদু লিল্লা-হি কাসীরান, ওয়ালহামদু লিল্লা-হি কাসীরান। ওয়ালহামদু লিল্লা-হি কাসী-রান ওয়াসুবহা-নাল্লাহি বুকরাতাঁও ওয়া আসীলা আউযু বিল্লা-হি মিনাশ শায়তানি, মিন নাফখিহী ওয়ানাফসিহী ওয়াহামযিহী" + "', bnReference = '" + "আবূ দাউদ ১/২০৩, নং ৭৬৪; ইবন মাজাহ্‌ ১/২৬৫, ৮০৭; আহমাদ, আহমাদ ৪/৮৫, নং ১৬৭৩৯। শাইখ শু‘আইব আল-আরনাউত তার মুসনাদের তাহকীকে এ হাদীসের সনদকে হাসান লি-গাইরিহি বলেছেন। আর আব্দুল কাদের আরনাউত ইবন তাইমিয়্যার ‘আল-কালেমুত তাইয়্যেব’ গ্রন্থের নং ৭৮, এর তাহকীক বলেন, এটি তার শাওয়াহেদ বা সমার্থবোধক হাদীসের দ্বারা সহীহ লি-গাইরিহী প্রমাণিত হয়। আর আলবানী তার সহীহুল কালেমিত তাইয়্যেব এর ৬২ নং এ হাদিসটি উল্লেখ করেছেন। তাছাড়া ইমাম মুসলিম ইবন উমর থেকে অনুরূপ হাদীস উদ্ধৃত করেছেন, তবে সেখানে একটি ঘটনা বর্ণিত হয়েছে। ১/৪২০, নং ৬০১" + "' WHERE id = 31")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনার জন্যই সকল হামদ-প্রশংসা; আসমানসমূহ, যমীন ও এ-দুটির মাঝে যা কিছু আছে আপনিই এগুলোর নূর (আলো)। আর আপনার জন্যই সব প্রশংসা; আসমানসমূহ, যমীন ও এ-দুটির মাঝে যা আছে আপনিই এসবের রক্ষণাবেক্ষণকারী-পরিচালক। আর আপনার জন্যই সকল প্রশংসা; আসমানসমূহ, যমীন ও এ-দুটির মাঝে যা কিছু আছে আপনিই এসবের রব্ব। আর আপনার জন্যই সব প্রশংসা; আসমানসমূহ, যমীন ও এ দু’টির মাঝে যা আছে তার সার্বভৌমত্ব আপনারই। আর আপনার জন্যই সকল প্রশংসা; আসমানসমূহ ও যমীনের রাজা আপনিই। আর আপনার জন্যই সকল প্রশংসা; আসমানসমূহ ও যমীনের রাজা আপনিই। আর আপনার জন্যই সকল প্রশংসা; আপনিই হক্ব, আপনার ওয়াদা হক্ব (বাস্তব ও সঠিক), আপনার বাণী হক্ব, আপনার সাক্ষাৎ লাভ হক্ব, জান্নাত হক্ব, জাহান্নাম হক্ব, নবীগণ হক্ব, মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম হক্ব এবং কিয়ামত হক্ব। হে আল্লাহ! আপনার কাছেই আত্মসমর্পণ করি, আপনার উপরই ভরসা করি, আপনার উপরই ঈমান আনি, আপনার দিকেই প্রত্যাবর্তন করি, আপনার সাহায্যেই বা আপনার জন্যই শত্রুর সাথে বিবাদে লিপ্ত হই, আর আপনার কাছেই বিচার পেশ করি; অতএব ক্ষমা করে দিন আমার গুনাহসমূহ— যা পূর্বে করেছি, যা পরে করেছি, যা আমি গোপন করেছি আর যা প্রকাশ্যে করেছি। আপনি ব্যতীত আর কোনো হক্ব ইলাহ নেই। আপনিই (কাউকে) করেন অগ্রগামী, আর আপনিই (কাউকে) করেন পশ্চাদগামী, আপনিই আমার ইলাহ। আপনি ব্যতীত আর কোনো হক্ব ইলাহ নেই।" + "', bnTransliteration = '" + "আল্লা-হুম্মা লাকাল হামদু আনতা নুরুস সামা-ওয়া-তি ওয়াল আরদি ওয়ামান ফীহিন্না ওয়া লাকাল হাম্‌দু। আনতা ক্বায়্যিমুস্ সামা-ওয়া-তি ওয়াল আরদি ওয়ামান ফীহিন্না, ওয়া লাকাল হামদু আনতা রববুস সামা-ওয়া-তি ওয়াল আরদি ওয়ামান ফীহিন্না, ওয়া লাকাল হাম্‌দু, লাকা মূলকুস সামা-ওয়া-তি ওয়াল আরদি ওয়ামান ফীহিন্না, ওয়া লাকাল হাম্‌দু,  আনতা মা-লিকুস সামা-ওয়া-তি ওয়াল আরদি ওয়া লাকাল হামদু, আনতাল হাক্কু, ওয়া ওয়া‘দুকাল হাক্কু, ওয়া ক্বাওলুকাল হাক্কু, ওয়া লিক্বা-উকাল হাক্কু, ওয়াল জান্নাতু হাক্কুন, ওয়ান না-রু হাক্কুন, ওয়ান নাবিয়্যূনা হাক্কুন, ওয়া মুহাম্মাদুন হাক্কুন, ওয়াস্‌সা‘আতু হাক্কুন আল্লা-হুম্মা লাকা আসলামতু, ওয়া আলাইকা তাওয়াক্কালতু ওয়াবিকা আ--মানতু, ওয়া ইলাইকা আনাবতু, ওয়া বিকা খা-সাম্‌তু, ওয়া ইলাইকা হা-কামতু, ফাগফির লী মা কাদ্দামতু, ওয়ামা আখখারতু, ওয়ামা আসরারতু, ওয়ামা আ‘লানতু, আনতাল মুকাদ্দিমু ওয়া আন্তাল্ মুআখখিরু, লা ইলা-হা ইল্লা আনতা আনতা ইলা-হী, লা ইলা-হা ইল্লা আন্তা" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ) ৩/৩, ১১/১১৬, ১৩/৩৭১, ৪২৩, ৪৬৫, নং ১১২০, ৬৩১৭, ৭৩৮৫, ৭৪৪২, ৭৪৯৯; ও মুসলিম সংক্ষিপ্তাকারে ১/৫৩২, নং ৭৬৯।" + "' WHERE id = 32")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমার মহান রব্বের পবিত্রতা ও মহিমা ঘোষণা করছি" + "', bnTransliteration = '" + "সুবহা-না রব্বিয়াল ‘আযীম" + "', bnReference = '" + "সুনানের গ্রন্থাকারগণ ও আহমাদ হাদীসটি উদ্ধৃত করেছেন। আবূ দাউদ, নং ৮৭০; তিরমিযী, নং ২৬২; নাসাঈ, নং ১০০৭; ইবন মাজাহ্‌, নং ৮৯৭; আহমাদ, নং ৩৫১৪ আরও দেখুন, সহীহুত তিরমিযী, ১/৮৩" + "' WHERE id = 33")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাদের রব্ব! আপনার পবিত্রতা ও মহিমা ঘোষণা করছি আপনার প্রশংসাসহ। হে আল্লাহ! আপনি আমাকে মাফ করে দিন।" + "', bnTransliteration = '" + "সুবহা-নাকাল্লা-হুম্মা রব্বানা ওয়াবিহামদিকা, আল্লা-হুম্মাগফির লী" + "', bnReference = '" + "বুখারী ১/৯৯, নং ৭৯৪; মুসলিম ১/৩৫০, নং ৪৮৪" + "' WHERE id = 34")
