        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার জন্যেই রুকু করেছি, আপনার উপরই ঈমান এনেছি এবং আপনার কাছেই আত্মসমর্পণ করেছি। আমার কান, আমার চোখ, আমার মস্তিষ্ক, আমার হাড়, আমার পেশী, সবই আপনার জন্য বিনয়াবনত। আর যা আমার পা বহন করে দাঁড়িয়ে আছে [মানে আমার সমগ্র সত্তা] তাও (আপনার জন্য বিনয়াবনত)" + "', bnTransliteration = '" + "আল্লা-হুম্মা লাকা রাকা‘তু, ওয়াবিকা আ-মানতু ওয়া লাকা আস্‌লামতু। খাশা‘আ লাকা সাম‘ঈ ওয়া বাসারী ওয়া মুখ্‌খী ওয়া ‘আযমী ওয়া ‘আসাবী ওয়ামাস্তাক্বাল্লাত বিহি কাদামী" + "', bnReference = '" + "মুসলিম ১/৫৩৪, নং ৭৭১; তাছাড়া চার সুনান গ্রন্থকারগণের মধ্যে ইবন মাজাহ ব্যতীত সবাই তা উদ্ধৃত করেছেন। আবূ দাউদ, নং ৭৬০, ৭৬১; তিরমিযী, নং ৩৪২১; নাসাঈ, নং ১০৪৯; তবে দুই ব্রাকেটের অংশ ইবন খুযাইমার শব্দ, নং ৬০৭; ইবন হিব্বান, নং ১৯০১" + "' WHERE id = 36")
