        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাদের রব্ব! আপনার প্রশংসাসহ আপনার পবিত্রতা ও মহিমা ঘোষণা করছি। হে আল্লাহ! আপনি আমাকে মাফ করে দিন।" + "', bnTransliteration = '" + "সুবহা-নাকাল্লা-হুম্মা রব্বানা ওয়া বিহামদিকা আল্লা-হুম্মাগফির লী" + "', bnReference = '" + "বুখারী, নং ৭৯৪; মুসলিম, নং ৪৮৪; দেখুন পরের দুআ (১৯.৩)" + "' WHERE id = 42")
