        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমার সমস্ত গুনাহ মাফ করে দিন— তার ক্ষুদ্র অংশ, তার বড় অংশ, আগের গুনাহ, পরের গুনাহ, প্রকাশ্য ও গোপন গুনাহ।" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফির লী যাম্বী কুল্লাহু; দিক্কাহু ওয়া জিল্লাহু, ওয়া আউয়ালাহু ওয়া ‘আখিরাহু, ওয়া ‘আলানিয়্যাতাহু ওয়া সিররাহু" + "', bnReference = '" + "মুসলিম ১/৩৫০, নং ৪৮৩" + "' WHERE id = 46")
