        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে; যাঁর নামের সাথে আসমান ও যমীনে কোনো কিছুই ক্ষতি করতে পারে না। আর তিনি সর্বশ্রোতা, মহাজ্ঞানী।”" + "', bnTransliteration = '" + "বিস্‌মিল্লা-হিল্লাযী লা ইয়াদ্বুররু মা‘আস্‌মিহী শাইউন ফিল্ আরদ্বি ওয়ালা ফিস্ সামা-ই, ওয়াহুয়াস্ সামী‘উল ‘আলীম" + "', bnReference = '" + "আবূ দাউদ, ৪/৩২৩, নং ৫০৮৮; তিরমিযী, ৫/৪৬৫, নং ৩৩৮৮; ইবন মাজাহ, নং ৩৮৬৯; আহমাদ, নং ৪৪৬। আরও দেখুন, সহীহ ইবন মাজাহ, ২/৩৩২ আর আল্লামা ইবন বায রাহিমাহুল্লাহ তাঁর ‘তুহফাতুল আখইয়ার’ গ্রন্থের ৩৯ পৃষ্ঠায় এটার সনদকে হাসান বলেছেন।" + "' WHERE id = 109")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহকে রব, ইসলামকে দীন ও মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে নবীরূপে গ্রহণ করে আমি সন্তুষ্ট।" + "', bnTransliteration = '" + "রদ্বীতু বিল্লা-হি রব্বান, ওয়াবিল ইসলা-মি দীনান, ওয়াবি মুহাম্মাদিন সাল্লাল্লা-হু ‘আলাইহি ওয়াসাল্লামা নাবিয়্যান" + "', bnReference = '" + "[১] আহমাদ ৪/৩৩৭; নং ১৮৯৬৭; নাসাঈ, আমালুল ইয়াওমি ওয়াল-লাইলাহ, নং ৪; ইবনুস সুন্নী, নং ৬৮; আবু দাউদ, ৪/৩১৮, নং ১৫৩১; তিরমিযী ৫/৪৬৫, নং ৩৩৮৯। আর ইবন বায রাহিমাহুল্লাহ ‘তুহফাতুল আখইয়ার’ এর ৩৯ পৃষ্ঠায় একে হাসান বলেছেন। [২] হাইসামী, মাজমাউয যাওয়াইদ ১০/১১৬; আলবানী, সাহীহাহ ?/৪২১; সহীহুত তারগীব ১/১৬০।" + "' WHERE id = 110")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে চিরঞ্জীব, হে চিরস্থায়ী! আমি আপনার রহমতের অসীলায় আপনার কাছে উদ্ধার কামনা করি, আপনি আমার সার্বিক অবস্থা সংশোধন করে দিন, আর আমাকে আমার নিজের কাছে নিমেষের জন্যও সোপর্দ করবেন না।" + "', bnTransliteration = '" + "ইয়া হাইয়্যু ইয়া ক্বাইয়্যূমু বিরহ্‌মাতিকা আস্তাগীসু, আসলিহ্‌ লী শা’নী কুল্লাহু, ওয়ালা তাকিলনী ইলা নাফসী ত্বারফাতা ‘আইন" + "', bnReference = '" + "হাকেম ১/৫৪৫, তিনি হাদীসটিকে সহীহ বলেছেন, আর যাহাবী তা সমর্থন করেছেন। আরও দেখুন, সহীহ আত-তারগীব ওয়াত-তারহীব ১/২৭৩" + "' WHERE id = 111")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমরা সন্ধ্যায় উপনীত হয়েছি, অনুরূপ যাবতীয় রাজত্বও সন্ধ্যায় উপনীত হয়েছে সৃষ্টিকুলের রব্ব আল্লাহ্‌র জন্য। হে আল্লাহ! আমি আপনার কাছে কামনা করি এই দিনের কল্যাণ: বিজয়, সাহায্য, নূর, বরকত ও হেদায়াত। আর আমি আপনার কাছে আশ্রয় চাই এ দিনের এবং এ দিনের পরের অকল্যাণ থেকে। আমরা বিকালে উপনীত হয়েছি, অনুরূপ যাবতীয় রাজত্বও বিকালে উপত হয়েছে সৃষ্টিকুলের রব্ব আল্লাহ্‌র জন্য। হে আল্লাহ, আমি আপনার কাছে কামনা করি এই রাতের কল্যাণ: বিজয়, সাহায্য, নূর, বরকত ও হেদায়াত। আর আমি আপনার কাছে আশ্রয় চাই এ রাতের এবং এ রাতের পরের অকল্যাণ থেকে।" + "', bnTransliteration = '" + "আসবাহ্‌না ওয়া আসবাহাল-মূলকু লিল্লা-হি রব্বিল ‘আলামীন। আল্লা-হুম্মা ইন্নী আস্আলুকা খাইরা হাযাল ইয়াওমি ফাতহাহু ওয়া নাসরাহু ওয়া নুরাহু ওয়া বারাকাতাহু ওয়া হুদা-হু। ওয়া আ‘ঊযু বিকা মিন শাররি মা ফীহি ওয়া শাররি মা বা‘দাহু আমসাইনা ওয়া আমসাল মুলকু লিল্লাহি রাব্বিল ‘আলামীন। আল্লা-হুম্মা ইন্নি আসআলুকা খাইরা হাযিহিল লাইলাতি ফাতহাহা ওয়া নাসরাহা, ওয়া নূরাহা, ওয়া বারাকাতাহা, ওয়া হুদাহা, ওয়া আ‘উযু বিকা মিন শাররি মা ফী-হা, ওয়া শাররি মা বা‘দাহা" + "', bnReference = '" + "আবূ দাউদ ৪/৩২২, নং ৫০৮৪; আর শু‘আইব ও আবদুল কাদের আরনাঊত যাদুল মা‘আদের সম্পাদনায় ২/৩৭৩ এর সনদকে হাসান বলেছেন।" + "' WHERE id = 112")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমরা সন্ধ্যায় উপনীত হয়েছি ইসলামের ফিত্বরাতের উপর, নিষ্ঠাপূর্ণ বাণী (তাওহীদ) এর উপর, আমাদের নবী মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর দ্বীনের উপর, আর আমাদের পিতা ইব্রাহীম আলাইহিস সালাম-এর মিল্লাতের উপর—যিনি ছিলেন একনিষ্ঠ মুসলিম এবং যিনি মুশরিকদের অন্তর্ভুক্ত ছিলেন না আমরা বিকালে উপনীত হয়েছি ইসলামের ফিত্বরাতের উপর, নিষ্ঠাপূর্ণ বাণী (তাওহীদ) এর উপর, আমাদের নবী মুহাম্মাদ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-এর দ্বীনের উপর, আর আমাদের পিতা ইব্রাহীম আলাইহিস সালাম-এর মিল্লাতের উপর—যিনি ছিলেন একনিষ্ঠ মুসলিম এবং যিনি মুশরিকদের অন্তর্ভুক্ত ছিলেন না" + "', bnTransliteration = '" + "আমসাইনা ‘আলা ফিত্বরাতিল ইসলামি ওয়া আলা কালিমাতিল ইখলাসি ওয়া আলা দ্বীনি নাবিয়্যিনা মুহাম্মাদিন সাল্লাল্লা-হু আলাইহি ওয়াসাল্লাম ওয়া আলা মিল্লাতি আবীনা ইবরা-হীমা হানীফাম মুসলিমাও ওয়ামা কা-না মিনাল মুশরিকীন আমসাইনা ‘আলা ফিত্বরাতিল ইসলামি ওয়া আলা কালিমাতিল ইখলাসি ওয়া আলা দ্বীনি নাবিয়্যিনা মুহাম্মাদিন সাল্লাল্লা-হু আলাইহি ওয়াসাল্লাম ওয়া আলা মিল্লাতি আবীনা ইবরা-হীমা হানীফাম মুসলিমাও ওয়ামা কা-না মিনাল মুশরিকীন" + "', bnReference = '" + "আহমাদ ৩/৪০৬, ৪০৭, নং ১৫৩৬০ ও নং ১৫৫৬৩; ইবনুস সুন্নী, আমালুল ইয়াওমি ওয়াল-লাইলাহ, নং ৩৪ আরও দেখুন, সহীহুল জামে‘উ ৪/২০৯।" + "' WHERE id = 113")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ অতি-পবিত্র সকল প্রশংসা আল্লাহর জন্য আল্লাহ অতি-মহান" + "', bnTransliteration = '" + "সুবহা-নাল্লাহ আলহামদুলিল্লা-হ আল্লা-হু আকবার" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ) ৭/৭১, নং ৩৭০৫; মুসলিম ৪/২০৯১, নং ২৭২৬।" + "' WHERE id = 114")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমরা আল্লাহর জন্য সন্ধ্যায় উপনীত হয়েছি, অনুরূপ যাবতীয় রাজত্বও সন্ধ্যায় উপনীত হয়েছে, আল্লাহ্‌র জন্য। সমুদয় প্রশংসা আল্লাহ্‌র জন্য। একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। রাজত্ব তাঁরই এবং প্রশংসাও তাঁর, আর তিনি সকল কিছুর উপর ক্ষমতাবান। হে রব্ব! এই দিনের মাঝে এবং এর পরে যা কিছু কল্যাণ আছে আমি আপনার নিকট তা প্রার্থনা করি। আর এই দিনের মাঝে এবং এর পরে যা কিছু অকল্যাণ আছে, তা থেকে আমি আপনার আশ্রয় চাই।  হে রব্ব! আমি আপনার কাছে আশ্রয় চাই অলসতা ও খারাপ বার্ধক্য থেকে। হে রব্ব!আমি আপনার কাছে আশ্রয় চাই জাহান্নামে আযাব হওয়া থেকে এবং কবরে আযাব হওয়া থেকে। আমরা আল্লাহর জন্য বিকালে উপনীত হয়েছি, অনুরূপ যাবতীয় রাজত্বও বিকালে উপনীত হয়েছে, আল্লাহ্‌র জন্য। সমুদয় প্রশংসা আল্লাহ্‌র জন্য। একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। রাজত্ব তাঁরই এবং প্রশংসাও তাঁর, আর তিনি সকল কিছুর উপর ক্ষমতাবান। হে রব্ব! এই রাতের মাঝে এবং এর পরে যা কিছু কল্যাণ আছে আমি আপনার নিকট তা প্রার্থনা করি। আর এই রাতের মাঝে এবং এর পরে যা কিছু অকল্যাণ আছে, তা থেকে আমি আপনার আশ্রয় চাই।  হে রব্ব! আমি আপনার কাছে আশ্রয় চাই অলসতা ও খারাপ বার্ধক্য থেকে। হে রব্ব!আমি আপনার কাছে আশ্রয় চাই জাহান্নামে আযাব হওয়া থেকে এবং কবরে আযাব হওয়া থেকে।" + "', bnTransliteration = '" + "আসবাহ্‌না ওয়া আসবাহাল মুলকু লিল্লাহি ওয়ালহাম্‌দু লিল্লাহি, লা ইলা-হা ইল্লাল্লা-হু ওয়াহ্‌দাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়াহুয়া আলা কুল্লি শাই’ইন ক্বাদীর। রব্বি আস্আলুকা খাইরা মা ফী হা-যাল ইয়াউমি ওয়া খাইরা মা বা‘দাহু, ওয়া আ‘ঊযু বিকা মিন শাররি মা ফী হা-যাল ইয়াউমি ওয়া শাররি মা বা‘দাহু। রব্বি আঊযু বিকা মিনাল কাসালি ওয়া সূইল-কিবারি। রব্বি আ‘ঊযু বিকা মিন ‘আযাবিন ফিন্না-রি ওয়া আযাবিন্ ফিল ক্বাবরি আমসাইনা ওয়া আমসাল মুলকু লিল্লাহি ওয়ালহাম্‌দু লিল্লাহি, লা ইলা-হা ইল্লাল্লা-হু ওয়াহ্‌দাহু লা শারীকা লাহু, লাহুল মুলকু ওয়া লাহুল হামদু, ওয়াহুয়া আলা কুল্লি শাই’ইন ক্বাদীর। রব্বি আস্আলুকা খাইরা মা ফী হাযিহিল লাইলাতি ওয়া খাইরা মা বা‘দাহা, ওয়া আ‘ঊযু বিকা মিন শাররি মা ফী হাযিহিল লাইলাতি ওয়া শাররি মা বা‘দাহা। রব্বি আঊযু বিকা মিনাল কাসালি ওয়া সূইল-কিবারি। রব্বি আ‘ঊযু বিকা মিন ‘আযাবিন ফিন্না-রি ওয়া আযাবিন্ ফিল ক্বাবরি" + "', bnReference = '" + "মুসলিম, ৪/২০৮৮, নং ২৭২৩" + "' WHERE id = 115")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "রাসূল তার প্রভুর পক্ষ থেকে যা তার কাছে নাযিল করা হয়েছে তার উপর ঈমান এনেছেন এবং মুমিনগণও। প্রত্যেকেই ঈমান এনেছে আল্লাহর উপর, তাঁর ফেরেশ্তাগণ, তাঁর কিতাবসমূহ এবং তাঁর রাসূলগণের উপর। আমরা তাঁর রাসূলগণের কারও মধ্যে তারতম্য করি না। আর তারা বলে, আমরা শুনেছি ও মেনে নিয়েছি। হে আমাদের রব! আপনার ক্ষমা প্রার্থনা করি এবং আপনার দিকেই প্রত্যাবর্তনস্থল। আল্লাহ্ কারো উপর এমন কোন দায়িত্ব চাপিয়ে দেন না যা তার সাধ্যাতীত। সে ভাল যা উপার্জন করে তার প্রতিফল তারই, আর মন্দ যা কামাই করে তার প্রতিফল তার উপরই বর্তায়। ‘হে আমাদের রব! যদি আমরা বিস্মৃত হই অথবা ভুল করি তবে আপনি আমাদেরকে পাকড়াও করবেন না। হে আমাদের রব! আমাদের পূর্ববর্তীগণের উপর যেমন বোঝা চাপিয়ে দিয়েছিলেন আমাদের উপর তেমন বোঝা চাপিয়ে দিবেন না। হে আমাদের রব! আপনি আমাদেরকে এমন কিছু বহন করাবেন না যার সামর্থ আমাদের নেই। আর আপনি আমাদের পাপ মোচন করুন, আমাদেরকে ক্ষমা করুন, আমাদের প্রতি দয়া করুন, আপনিই আমাদের অভিভাবক। অতএব কাফির সম্প্রদায়ের বিরুদ্ধে আমাদেরকে সাহায্য করুন। [১]" + "', bnTransliteration = '" + "আ-মানার রাসূলু বিমা উনযিলা ইলাইহি মির রব্বিহী ওয়াল মু’মিনূন। কুল্লুন আ-মানা বিল্লা-হি ওয়া মালা-ইকাতিহী ওয়াকুতুবিহী ওয়া রুসুলিহ, লা নুফাররিক্বু বাইনা আহাদিম মির রুসুলিহ, ওয়া ক্বালু সামি‘না ওয়া আতা‘না গুফ্‌রা-নাকা রব্বানা ওয়া ইলাইকাল মাসীর। লা ইয়ুকাল্লিফুল্লাহু নাফ্‌সান ইল্লা উস‘আহা লাহা মা কাসাবাত ওয়া আলাইহা মাক্তাসাবাত রব্বানা লা তুআখিয্‌না ইন নাসীনা আও আখ্‌ত্বা’না। রব্বনা ওয়ালা তাহ্‌মিল ‘আলাইনা ইসরান কামা হামালতাহু ‘আলাল্লাযীনা মিন ক্বাবলিনা। রব্বনা ওয়ালা তুহাম্মিলনা মা-লা ত্বা-ক্বাতা লানা বিহী। ওয়া‘ফু আন্না ওয়াগফির লানা ওয়ারহামনা আনতা মাওলা-না ফানসুরনা ‘আলাল ক্বাউমিল কাফিরীন" + "', bnReference = '" + "[১] সূরা আল-বাকারা ২৮৫-২৮৬।  [২] বুখারী, ফাতহুল বারীসহ, ৯/৯৪, ৪০০৮; মুসলিম ১/৫৫৪, নং ৮০৭।" + "' WHERE id = 116")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি আশ্রয় গ্রহণ করছি আল্লাহর পরিপূর্ণ বাক্যাবলির, যেগুলোকে অতিক্রম করতে পারে না কোনো পুণ্যবান বা কোনো পাপী, তিনি যা কিছু সৃষ্টি করেছেন, বানিয়েছেন ও ছড়িয়ে দিয়েছেন তার অনিষ্ট থেকে, যা কিছু আসমান থেকে অবতরণ করে তার অনিষ্ট থেকে, যা কিছু আসমানে উঠে তার অনিষ্ট থেকে, যা কিছু যমিনে সৃষ্ট-ছড়ানো তার অনিষ্ট থেকে, যা কিছু যমিন থেকে বের হয় তার অনিষ্ট থেকে, রাত ও দিনের অনিষ্ট থেকে এবং সকল আগন্তুকের অনিষ্ট থেকে, শুধু যে আগন্তুক কল্যাণ-সহ আগমন করে সে ব্যতীত, হে মহা-দয়াময়।" + "', bnTransliteration = '" + "আ‘ঊযু বিকালিমা-তিল্লাহিত তাম্মা-তিল্লাতী লা- ইউজাওিযুহুন্না র্বারুন ওয়ালা- ফা-জির, মিন র্শারি মা- খালাক্কা ওয়া যারাআ ওয়া বারাআ, ওয়া মিন র্শারি মা ইয়ানযিলু মিনাস সামা-য়ি ওয়া মিন র্শারি মা ইয়া‘অরুজু ফীহা-, ওয়া মিন র্শারি মা যারাআ ফিল আরদ্বি, ওয়া মিন র্শারি মা ইয়া‘খরুজু মিন্হা-, ওয়া মিন র্শারিল্লাইলি ওয়ান নাহা-রি, ওয়া মিন র্শারি কুল্লি ত্বা-রিক্কিন ইল্লা- ত্বারিক্কান ইয়াত্বরুক্কু বিখাইরিন ইয়া- রা‘হমা-ন।" + "', bnReference = '" + "আহমাদ, আল-মুসনাদ (আরনউত সম্পাদিত) ৩/৪১৯; আবূ ইয়ালা, আল-মুসনাদ (আসাদ সম্পাদিত) ১২/২৩৭; তাবারানী, আল-মু''জামুল আউসাত ৫/৩১৫; আলবানী, সহীহাহ; মুখতাসারাহ (শামিলা) ২/৪৯৫, ৭/১৯৬; সহীহুত তারগীব ২/১২০; রাহে বেলায়াত - যিকর নং ১৬৫" + "' WHERE id = 117")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি সালাত ও সালাম পেশ করুন আমাদের নবী মুহাম্মাদের উপর।" + "', bnTransliteration = '" + "আল্লা-হুম্মা সাল্লি ওয়াসাল্লিম ‘আলা নাবিয়্যিনা মুহাম্মাদ" + "', bnReference = '" + "তাবরানী হাদীসটি দু’ সনদে সংকলন করেন, যার একটি উত্তম। দেখুন, মাজমা‘উয যাওয়ায়েদ ১০/১২০; সহীহুত তারগীব ওয়াত তারহীব ১/২৭৩" + "' WHERE id = 118")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "বলুন, তিনি আল্লাহ্, এক-অদ্বিতীয়। আল্লাহ্ হচ্ছেন ‘সামাদ’ (তিনি কারো মুখাপেক্ষী নন, সকলেই তাঁর মুখাপেক্ষী)। তিনি কাউকেও জন্ম দেন নি এবং তাঁকেও জন্ম দেয়া হয় নি। আর তাঁর সমতুল্য কেউই নেই। বলুন, আমি আশ্রয় প্রার্থনা করছি ঊষার রবের। তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে। ‘আর অনিষ্ট হতে রাতের অন্ধকারের, যখন তা গভীর হয়। আর অনিষ্ট হতে সমস্ত নারীদের, যারা গিরায় ফুঁক দেয়। আর অনিষ্ট হতে হিংসুকের, যখন সে হিংসা করে। বলুন, আমি আশ্রয় প্রার্থনা করছি মানুষের রবের, মানুষের অধিপতির, মানুষের ইলাহের কাছে, আত্মগোপনকারী কুমন্ত্রণাদাতার অনিষ্ট হতে; যে কুমন্ত্রণা দেয় মানুষের অন্তরে, জিনের মধ্য থেকে এবং মানুষের মধ্য থেকে।" + "', bnTransliteration = '" + "ক্বুল হুওয়াল্লা-হু আহাদ। আল্লাহুস্ সামাদ। লাম ইয়ালিদ ওয়া লাম ইউলাদ। ওয়া লাম ইয়াকুল্লাহু কুফুওয়ান আহাদ ক্বুল আ‘উযু বিরব্বিল ফালাক্ব। মিন শাররি মা খালাক্ব। ওয়া মিন শাররি গা-সিক্বিন ইযা ওয়াক্বাব। ওয়া মিন শাররিন নাফফা-সা-তি ফিল ‘উক্বাদ। ওয়া মিন শাররি হা-সিদিন ইযা হাসাদ ক্বুল ‘আউযু বিরাব্বিন্না-স। মালিকিন্না-সি, ইলা-হিন্নাসি, মিন শাররিল ওয়াসওয়া-সিল খান্না-স, আল্লাযি ইউওয়াসউইসু ফী সুদূরিন না-সি, মিনাল জিন্নাতি ওয়ান্না-স।" + "', bnReference = '" + "আবূ দাউদ ৪/৩২২, নং ৫০৮২; তিরমিযী ৫/৫৬৭, নং ৩৫৭৫। আরও দেখুন, সহীহুত তিরমিযী, ৩/১৮২" + "' WHERE id = 119")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "বিতাড়িত শয়তান থেকে আমি আল্লাহ্‌র আশ্রয় নিচ্ছি। আল্লাহ্, তিনি ছাড়া কোনো সত্য ইলাহ্ নেই। তিনি চিরঞ্জীব, সর্বসত্তার ধারক। তাঁকে তন্দ্রাও স্পর্শ করতে পারে না, নিদ্রাও নয়। আসমানসমূহে যা রয়েছে ও যমীনে যা রয়েছে সবই তাঁর। কে সে, যে তাঁর অনুমতি ব্যতীত তাঁর কাছে সুপারিশ করবে? তাদের সামনে ও পিছনে যা কিছু আছে তা তিনি জানেন। আর যা তিনি ইচ্ছে করেন তা ছাড়া তাঁর জ্ঞানের কোনো কিছুকেই তারা পরিবেষ্টন করতে পারে না। তাঁর ‘কুরসী’ আসমানসমূহ ও যমীনকে পরিব্যাপ্ত করে আছে; আর এ দুটোর রক্ষণাবেক্ষণ তাঁর জন্য বোঝা হয় না। আর তিনি সুউচ্চ সুমহান।" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বানির রাজীম আল্লা-হু লা ইলা-হা ইল্লা হুওয়াল হাইয়্যূল কাইয়্যূমু লা তা’খুযুহু সিনাতুঁও ওয়ালা নাউম। লাহূ মা-ফিসসামা-ওয়া-তি ওয়ামা ফিল আরদ্বি। মান যাল্লাযী ইয়াশফা‘উ ‘ইনদাহূ ইল্লা বিইযনিহী। ইয়া‘লামু মা বাইনা আইদীহিম ওয়ামা খালফাহুম। ওয়ালা ইয়ুহীতূনা বিশাইইম মিন্ ইলমিহী ইল্লা বিমা শাআ। ওয়াসি‘আ কুরসিয়্যুহুস সামা-ওয়া-তি ওয়াল আরদ্ব। ওয়ালা ইয়াউদুহূ হিফযুহুমা ওয়া হুয়াল ‘আলিয়্যূল ‘আযীম" + "', bnReference = '" + "হাদীসটি হাকিম সংকলন করেছেন, ১/৫৬২ আর শাইখ আলবানী একে সহীহুত তারগীব ওয়াত-তারহীবে সহীহ বলেছেন ১/২৭৩ আর তিনি একে নাসাঈ, তাবারানীর দিকে সম্পর্কযুক্ত করেছেন এবং বলেছেন, তাবারানীর সনদ ‘জাইয়্যেদ’ বা ভালো।" + "' WHERE id = 120")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "রাসূল তার প্রভুর পক্ষ থেকে যা তার কাছে নাযিল করা হয়েছে তার উপর ঈমান এনেছেন এবং মুমিনগণও। প্রত্যেকেই ঈমান এনেছে আল্লাহর উপর, তাঁর ফেরেশ্তাগণ, তাঁর কিতাবসমূহ এবং তাঁর রাসূলগণের উপর। আমরা তাঁর রাসূলগণের কারও মধ্যে তারতম্য করি না। আর তারা বলে, আমরা শুনেছি ও মেনে নিয়েছি। হে আমাদের রব! আপনার ক্ষমা প্রার্থনা করি এবং আপনার দিকেই প্রত্যাবর্তনস্থল। আল্লাহ্ কারো উপর এমন কোন দায়িত্ব চাপিয়ে দেন না যা তার সাধ্যাতীত। সে ভাল যা উপার্জন করে তার প্রতিফল তারই, আর মন্দ যা কামাই করে তার প্রতিফল তার উপরই বর্তায়। ‘হে আমাদের রব! যদি আমরা বিস্মৃত হই অথবা ভুল করি তবে আপনি আমাদেরকে পাকড়াও করবেন না। হে আমাদের রব! আমাদের পূর্ববর্তীগণের উপর যেমন বোঝা চাপিয়ে দিয়েছিলেন আমাদের উপর তেমন বোঝা চাপিয়ে দিবেন না। হে আমাদের রব! আপনি আমাদেরকে এমন কিছু বহন করাবেন না যার সামর্থ আমাদের নেই। আর আপনি আমাদের পাপ মোচন করুন, আমাদেরকে ক্ষমা করুন, আমাদের প্রতি দয়া করুন, আপনিই আমাদের অভিভাবক। অতএব কাফির সম্প্রদায়ের বিরুদ্ধে আমাদেরকে সাহায্য করুন। [১]" + "', bnTransliteration = '" + "আ-মানার রাসূলু বিমা উনযিলা ইলাইহি মির রব্বিহী ওয়াল মু’মিনূন। কুল্লুন আ-মানা বিল্লা-হি ওয়া মালা-ইকাতিহী ওয়াকুতুবিহী ওয়া রুসুলিহ, লা নুফাররিক্বু বাইনা আহাদিম মির রুসুলিহ, ওয়া ক্বালু সামি‘না ওয়া আতা‘না গুফ্‌রা-নাকা রব্বানা ওয়া ইলাইকাল মাসীর। লা ইয়ুকাল্লিফুল্লাহু নাফ্‌সান ইল্লা উস‘আহা লাহা মা কাসাবাত ওয়া আলাইহা মাক্তাসাবাত রব্বানা লা তুআখিয্‌না ইন নাসীনা আও আখ্‌ত্বা’না। রব্বনা ওয়ালা তাহ্‌মিল ‘আলাইনা ইসরান কামা হামালতাহু ‘আলাল্লাযীনা মিন ক্বাবলিনা। রব্বনা ওয়ালা তুহাম্মিলনা মা-লা ত্বা-ক্বাতা লানা বিহী। ওয়া‘ফু আন্না ওয়াগফির লানা ওয়ারহামনা আনতা মাওলা-না ফানসুরনা ‘আলাল ক্বাউমিল কাফিরীন" + "', bnReference = '" + "[১] সূরা আল-বাকারা ২৮৫-২৮৬।  [২] বুখারী, ফাতহুল বারীসহ, ৯/৯৪, ৪০০৮; মুসলিম ১/৫৫৪, নং ৮০৭।" + "' WHERE id = 121")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমার রব! আপনার নামে আমি আমার পার্শ্বদেশ রেখেছি (শুয়েছি) এবং আপনারই নাম নিয়ে আমি তা উঠাবো। যদি আপনি (ঘুমন্ত অবস্থায়) আমার প্রাণ আটকে রাখেন, তবে আপনি তাকে দয়া করুন। আর যদি আপনি তা ফেরত পাঠিয়ে দেন, তাহলে আপনি তার হেফাযত করুন যেভাবে আপনি আপনার সৎকর্মশীল বান্দাগণকে হেফাযত করে থাকেন।" + "', bnTransliteration = '" + "বিইসমিকারব্বী ওয়াদা‘তু জাম্বী, ওয়া বিকা আরফা‘উহু। ফাইন্ আম্‌সাক্তা নাফ্‌সী ফারহামহা, ওয়াইন আরসালতাহা ফাহ্‌ফায্‌হা বিমা তাহ্‌ফাযু বিহী ‘ইবা-দাকাস সা-লিহীন" + "', bnReference = '" + "বুখারী, ফাতহুল বারীসহ ১১/১২৬, নং ৬৩২০; মুসলিম ৪/২০৮৪, নং ২৭১[৪] হাদীসে বর্ণিত صنفة إزاره শব্দের অর্থ হচ্ছে, চাদরের পার্শ্বদিকস্থ অংশ। এর জন্য দেখুন, নিহায়া ফী গারিবিল হাদীস ওয়াল আসার’ ‘صنف’" + "' WHERE id = 122")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! নিশ্চয় আপনি আমার আত্মাকে সৃষ্টি করেছেন এবং আপনি তার মৃত্যু ঘটাবেন। তার মৃত্যু ও তার জীবন আপনার মালিকানায়। যদি তাকে বাঁচিয়ে রাখেন তাহলে আপনি তার হেফাযত করুন, আর যদি তার মৃত্যু ঘটান তবে তাকে মাফ করে দিন। হে আল্লাহ! আমি আপনার কাছে নিরাপত্তা চাই।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নাকা খালাক্তা নাফসী ওয়া আন্তা তাওয়াফ্‌ফাহা। লাকা মামা-তুহা ওয়া মাহ্‌ইয়া-হা। ইন্ আহ্ইয়াইতাহা ফাহ্‌ফায্‌হা ওয়াইন আমাত্তাহা ফাগফির লাহা। আল্লা-হুম্মা ইন্নী আস্আলুকাল ‘আ-ফিয়াতা" + "', bnReference = '" + "মুসলিম ৪/২০৮৩, নং ২৭১২; আহমাদ, তাঁর শব্দে ২/৭৯, নং ৫৫০২" + "' WHERE id = 123")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাকে আপনার আযাব থেকে রক্ষা করুন, যেদিন আপনি আপনার বান্দাদেরকে পুনর্জীবিত করবেন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ক্বিনী ‘আযা-বাকা ইয়াওমা তাব‘আছু ‘ইবা-দাকা" + "', bnReference = '" + "আবূ দাউদ, শব্দ তাঁরই, ৪/৩১১, নং ৫০৪৫; তিরমিযী, নং ৩৩৯৮; আরও দেখুন, সহীহুত তিরমিযী, ৩/১৪৩; সহীহ আবী দাঊদ, ৩/২৪০।" + "' WHERE id = 124")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ ! আপনার নাম নিয়েই আমি মরছি (ঘুমাচ্ছি) এবং আপনার নাম নিয়েই জীবিত (জাগ্রত) হবো।" + "', bnTransliteration = '" + "বিস্‌মিকাল্লা-হুম্মা আমূতু ওয়া আহ্ইয়া" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ) ১১/১১৩, নং ৬৩২৪; মুসলিম ৪/২০৮৩, নং ২৭১১" + "' WHERE id = 125")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ অতি-পবিত্র সকল প্রশংসা আল্লাহর জন্য আল্লাহ অতি-মহান" + "', bnTransliteration = '" + "সুবহা-নাল্লাহ আলহামদুলিল্লা-হ আল্লা-হু আকবার" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ) ৭/৭১, নং ৩৭০৫; মুসলিম ৪/২০৯১, নং ২৭২৬।" + "' WHERE id = 126")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! হে সপ্ত আকাশের রব্ব, যমিনের রব্ব, মহান ‘আরশের রব্ব, আমাদের রব্ব ও প্রত্যেক বস্তুর রব্ব, হে শস্য-বীজ ও আঁটি বিদীর্ণকারী, হে তাওরাত, ইনজীল ও কুরআন নাযিলকারী, আমি প্রত্যেক এমন বস্তুর অনিষ্ট থেকে আপনার নিকট আশ্রয় প্রার্থনা করি, যার (মাথার) অগ্রভাগ আপনি ধরে রেখেছেন (নিয়ন্ত্রণ করছেন)। হে আল্লাহ! আপনিই প্রথম, আপনার পূর্বে কিছুই ছিল না; আপনি সর্বশেষ, আপনার পরে কোনো কিছু থাকবে না; আপনি সব কিছুর উপরে, আপনার উপরে কিছুই নেই; আপনি সর্বনিকটে, আপনার চেয়ে নিকটবর্তী কিছু নেই, আপনি আমাদের সমস্ত ঋণ পরিশোধ করে দিন এবং আমাদেরকে অভাবগ্রস্ততা থেকে অভাবমুক্ত করুন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা রব্বাস্ সামা-ওয়া-তিস্ সাব‘ই ওয়া রব্বাল ‘আরশিল ‘আযীম, রব্বনা ওয়া রব্বা কুল্লি শাই’ইন্, ফা-লিক্বাল হাব্বি ওয়ান-নাওয়া, ওয়া মুনযিলাত্-তাওরা-তি ওয়াল ইনজীলি ওয়াল ফুরক্বা-ন, আ‘ঊযু বিকা মিন শাররি কুল্লি শাই’ইন্ আনতা আ-খিযুম-বিনা-সিয়াতিহি। আল্লা-হুম্মা আনতাল আউওয়ালু ফালাইসা ক্বাবলাকা শাইউন। ওয়া আনতাল আ-খিরু ফালাইসা বা‘দাকা শাইউন। ওয়া আনতায যা-হিরু ফালাইসা ফাওক্বাকা শাইউন। ওয়া আনতাল বা-ত্বিনু ফালাইসা দূনাকা শাইউন। ইক্বদ্বি ‘আন্নাদ্-দাইনা ওয়া আগনিনা মিনাল ফাক্বরি" + "', bnReference = '" + "মুসলিম ৪/২০৮৪, নং ২৭১৩" + "' WHERE id = 127")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "সকল প্রশংসা আল্লাহ্‌র জন্য, যিনি আমাদেরকে আহার করিয়েছেন, পান করিয়েছেন, আমাদের প্রয়োজন পূর্ণ করেছেন এবং আমাদেরকে আশ্রয় দিয়েছেন। কেননা, এমন বহু লোক আছে যাদের প্রয়োজনপূর্ণকারী কেউ নেই এবং যাদের আশ্রয়দানকারীও কেউ নেই।" + "', bnTransliteration = '" + "আলহামদু লিল্লা-হিল্লাযী আত‘আমানা, ওয়া সাক্বা-না, ওয়া কাফা-না, ওয়া আ-ওয়ানা, ফাকাম্ মিম্মান লা কা-ফিয়া লাহু, ওয়ালা মু’উইয়া" + "', bnReference = '" + "মুসলিম ৪/২০৮৫, নং ২৭১৫।" + "' WHERE id = 128")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! হে গায়েব ও উপস্থিতের জ্ঞানী, হে আসমানসমূহ ও যমীনের স্রষ্টা, হে সব কিছুর রব্ব ও মালিক! আমি সাক্ষ্য দিচ্ছি যে, আপনি ছাড়া আর কোনো হক্ব ইলাহ নেই। আমি আপনার কাছে আশ্রয় চাই আমার আত্মার অনিষ্ট থেকে, শয়তানের অনিষ্টতা থেকে ও তার শির্ক বা তার ফাঁদ থেকে, আমার নিজের উপর কোনো অনিষ্ট করা, অথবা কোনো মুসলিমের দিকে তা টেনে নেওয়া থেকে।" + "', bnTransliteration = '" + "আল্লা-হুম্মা আ-লিমাল গাইবি ওয়াশ্‌শাহা-দাতি ফা-ত্বিরাস সামা-ওয়া-তি ওয়াল আরদ্বি, রব্বা কুল্লি শাই’ইন ওয়া মালীকাহু, আশহাদু আল-লা ইলা-হা ইল্লা আনতা। আ‘উযু বিকা মিন শাররি নাফ্‌সী ওয়া মিন শাররিশ শাইত্বা-নি ওয়াশারাকিহী ওয়া আন আক্বতারিফা ‘আলা নাফ্‌সী সূওআন আউ আজুররাহূ ইলা মুসলিম" + "', bnReference = '" + "তিরমিযী, নং ৩৩৯২; আবূ দাউদ, নং ৫০৬৭। আরও দেখুন, সহীহুত তিরমিযী, ৩/১৪২" + "' WHERE id = 129")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "ঘুমানোর পূর্বে সূরা আস-সাজদাহ (সূরা ৩২) এবং সূরা আল-মুলক (সূরা ৬৭) তিলাওয়াত করা সুন্নাত।" + "', bnTransliteration = '" + "আলিফ লাম মীম তানযীলুস সাজদাহ্ ও তাবারাকাল্লাযী বিয়াদিহিল মুলক" + "', bnReference = '" + "তিরমিযী ও নাসাঈ; সহীহুল জামি‘ ৪/২৫৫, নং ৫০৭২" + "' WHERE id = 130")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি নিজেকে আপনার কাছে সঁপে দিলাম। আমার যাবতীয় বিষয় আপনার কাছেই সোপর্দ করলাম, আমার চেহারা আপনার দিকেই ফিরালাম, আর আমার পৃষ্ঠদেশকে আপনার দিকেই ন্যস্ত করলাম; আপনার প্রতি অনুরাগী হয়ে এবং আপনার ভয়ে ভীত হয়ে। একমাত্র আপনার নিকট ছাড়া আপনার (পাকড়াও) থেকে বাঁচার কোনো আশ্রয়স্থল নেই এবং কোনো মুক্তির উপায় নেই। আমি ঈমান এনেছি আপনার নাযিলকৃত কিতাবের উপর এবং আপনার প্রেরিত নবীর উপর।”" + "', bnTransliteration = '" + "আল্লা-হুম্মা আস্‌লামতু নাফ্‌সী ইলাইকা, ওয়া ফাউওয়াদ্বতু আমরী ইলাইকা, ওয়া ওয়াজ্জাহ্‌তু ওয়াজহিয়া ইলাইকা, ওয়াআলজা’তু যাহ্‌রী ইলাইকা, রাগবাতান ওয়া রাহবাতান ইলাইকা। লা মালজা’আ ওয়ালা মান্‌জা মিনকা ইল্লা ইলাইকা। আ-মানতু বিকিতা-বিকাল্লাযী আনযালতা ওয়াবিনাবিয়্যিকাল্লাযী আরসালতা" + "', bnReference = '" + "[১] বুখারী, (ফাতহুল বারীসহ) ১১/১১৩, নং ৬৩১৩; মুসলিম ৪/২০৮১, নং ২৭১০। [২] বুখারী (১০০-কিতাবুত তাওহীদ, ৩৪-বাব...আনযালাহু বিইলমিহি...) ৬/২৭২২ (ভা ২/১১১৫); মুসলিম (৪৮-কিতাবুদ্দাআওয়াত, ১৭-বাব মা ইয়াকূল ইনদান নাওম) ৪/২০৮১ (ভারতীয় ২/৩৪৮)।" + "' WHERE id = 131")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "মহাপ্রতাপশালী এক আল্লাহ ছাড়া আর কোনো হক্ব ইলাহ নেই। (তিনি) আসমানসমূহ, যমীন এবং এ দু’য়ের মধ্যস্থিত সবকিছুর রব্ব, প্রবলপরাক্রমশালী, পরম ক্ষমাশীল।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হুল ওয়াহিদুল কাহ্‌হারু রব্বুস্ সামা-ওয়া-তি ওয়াল-আরদ্বি ওয়ামা বাইনাহুমাল-‘আযীযুল গাফ্‌ফার" + "', bnReference = '" + "হাদীসটি সংকলন করেছেন, হাকেম এবং তিনি তা সহীহ বলেছেন, আর ইমাম যাহাবী তাকে সমর্থন করেছেন, ১/৫৪০; নাসাঈ, আমালুল ইয়াওমি ওয়াল্লাইলা, নং ২০২; ইবনুস সুন্নী, নং ৭৫৭। আরও দেখুন, সহীহুল জামে‘ ৪/২১৩" + "' WHERE id = 132")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি আশ্রয় চাই আল্লাহ্‌র পরিপূর্ণ কালামসমূহের অসীলায় তাঁর ক্রোধ থেকে, তাঁর শাস্তি থেকে, তাঁর বান্দাদের অনিষ্ট থেকে, শয়তানদের কুমন্ত্রণা থেকে এবং তাদের উপস্থিতি থেকে" + "', bnTransliteration = '" + "আ‘ঊযু বিকালিমা-তিল্লাহিত্তা-ম্মাতি মিন্ গাদ্বাবিহি ওয়া ইক্বা-বিহি ওয়া শাররি ‘ইবা-দিহি ওয়ামিন হামাযা-তিশ্‌শায়া-ত্বীনি ওয়া আন ইয়াহ্‌দুরূন" + "', bnReference = '" + "আবূ দাঊদ ৪/১২, নং ৩৮৯৩; তিরমিযী, নং ৩৫২৮। আরও দেখুন, সহীহুত তিরমিযী ৩/১৭১" + "' WHERE id = 133")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "১. বাম দিকে তিনবার থুতু ফেলার মতো হালকা ফুঁক দিবে। ২. তিনবার শয়তান ও অনিষ্ট থেকে আল্লাহর আশ্রয় চাইবে। ৩. যে কাতে শুয়েছিল তা পরিবর্তন করবে।" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বা-নির রাজীম" + "', bnReference = '" + "মুসলিম ৪/১৭৭২, নং ২২৬১; ফাতহুল বারী ১২/৩৭০" + "' WHERE id = 134")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "স্বপ্নে অপছন্দনীয় কিছু দেখলে তা কারও কাছে প্রকাশ করবে না এবং ইচ্ছা হলে উঠে সালাত আদায় করবে।" + "', bnTransliteration = '" + "ইয়াকূমু ইউসাল্লী ইন আরাদা যালিক" + "', bnReference = '" + "মুসলিম ৪/১৭৭৩, নং ২২৬৩" + "' WHERE id = 135")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি যাদেরকে হেদায়াত করেছেন তাদের মধ্যে আমাকেও হেদায়াত দিন, আপনি যাদেরকে নিরাপত্তা প্রদান করেছেন তাদের মধ্যে আমাকেও নিরাপত্তা দিন, আপনি যাদের অভিভাবকত্ব গ্রহণ করেছেন, তাদের মধ্যে আমার অভিভাবকত্বও গ্রহণ করুন, আপনি আমাকে যা দিয়েছেন তাতে বরকত দিন। আপনি যা ফয়সালা করেছেন তার অকল্যাণ থেকে আমাকে রক্ষা করুন। কারণ আপনিই চুড়ান্ত ফয়সালা দেন, আপনার বিপরীতে ফয়সালা দেওয়া হয় না। আপনি যার সাথে বন্ধুত্ব করেছেন সে অবশ্যই অপমানিত হয় না [এবং আপনি যার সাথে শত্রুতা করেছেন সে সম্মানিত হয় না] আপনি বরকতপূর্ণ হে আমাদের রব্ব! আর আপনি সুউচ্চ-সুমহান" + "', bnTransliteration = '" + "আল্লা-হুম্মাহদিনী ফীমান হাদাইতা ওয়া ‘আ-ফিনী ফীমান ‘আ-ফাইতা ওয়া তাওয়াল্লানী ফীমান তাওয়াল্লাইতা ওয়াবা-রিক লী ফীমা আ‘ত্বাইতা ওয়াক্বিনী শাররা মা ক্বাদাইতা ফাইন্নাকা তাক্ব‌দ্বী ওয়ালা ইউক্ব্‌দ্বা ‘আলাইকা। ইন্নাহু লা ইয়াযিল্লু মাও ওয়া-লাইতা, [ওয়ালা ইয়া‘ইয্যু মান ‘আ-দাইতা] তাবা-রক্‌তা রব্বানা ওয়া তা‘আ-লাইতা" + "', bnReference = '" + "সুনান গ্রন্থকারগণ, আহমাদ, দারামী ও বাইহাকী এ হাদীসটি সংকলন করেছেন। আবূ দাউদ, নং ১৪২৫; তিরমিযী, নং ৪৬৪; নাসাঈ, নং ১৭৪৪; ইবন মাজাহ, নং ১১৭৮; আহমাদ, নং ১৭১৮; দারামী, নং ১৫৯২; হাকিম, ৩/১৭২; বাইহাকী, ২/২০৯। আর দু’ ব্রাকেটের মাঝখানের অংশ বাইহাকীর। আরও দেখুন, সহীহুত তিরমিযী ১/১৪৪, সহীহ ইবন মাজাহ্‌, ১/১৯৪; ইরওয়াউল গালীল, লিল আলবানী, ২/১৭২" + "' WHERE id = 136")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার সন্তুষ্টির মাধ্যমে অসন্তুষ্টি থেকে, আর আপনার নিরাপত্তার মাধ্যমে আপনার শাস্তি থেকে আশ্রয় চাই। আর আমি আপনার নিকটে আপনার (পাকড়াও) থেকে আশ্রয় চাই। আমি আপনার প্রশংসা গুনতে সক্ষম নই; আপনি সেরূপই, যেরূপ প্রশংসা আপনি নিজের জন্য করেছেন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী আঊযুবিরিদ্বা-কা মিন সাখাত্বিকা, ওয়া বিমু‘আ-ফা-তিকা মিন ‘উক্বুবাতিকা, ওয়া আঊযু বিকা মিনকা, লা উহ্‌সী সানা-আন আলাইকা, আনতা কামা আসনাইতা ‘আলা নাফসিকা" + "', bnReference = '" + "সুনান গ্রন্থকারগণ ও আহমাদ হাদীসটি সংকলন করেছেন। আবূ দাউদ, নং ১৪২৭; তিরমিযী, নং ৩৫৬৬; নাসাঈ, নং ১৭৪৬; ইবন মাজাহ্‌, নং ১১৭৯; আহমাদ, নং ৭৫১ আরও দেখুন, সহীহুত তিরমিযী, ৩/১৮০; সহীহ ইবন মাজাহ্‌, ১/১৯৪, আল-ইরওয়া, ২/১৭৫।" + "' WHERE id = 137")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, আমরা আপনার কাছে সাহায্য প্রার্থনা করছি, আপনার কাছে ক্ষমা প্রার্থনা করছি, আপনার প্রশংসা ও গুণকীর্তন করছি। আমরা আপনার কৃতজ্ঞতা প্রকাশ করি এবং আপনার প্রতি অকৃতজ্ঞতা-অবিশ্বাস প্রকাশ করি না। আমরা বিচ্ছিন্ন হই এবং পরিত্যাগ করি তাকে যে আপনার অবাধ্য হয়। হে আল্লাহ, আমরা কেবলমাত্র আপনারই ইবাদত করি, কেবলমাত্র আপনার জন্যই সালাত আদায় করি এবং সাজদা করি, শুধু আপনার দিকেই ধাবিত হই এবং আপনার আনুগত্যেই কর্ম করি। আমরা আপনার প্রকৃত শাস্তির ভয় করি এবং আপনার রহমত আশা করি। নিশ্চয় আপনার শাস্তি কাফিরদেরকে স্পর্শ করবে।” হে আল্লাহ, ক্ষমা করুন আমাদেরকে, এবং মুমিন পুরুষদেরকে এবং মুমিন নারীদেরকে, এবং মুসলিম পুরুষদেরকে এবং মুসলিম নারীদেরকে, তাদের অন্তরের মধ্যে সম্প্রীতি প্রদান করুন, তাদের আভ্যন্তরীণ সম্পর্ক সুন্দর করে দিন, আপনার ও তাদের শত্র“দের উপর তাদের বিজয় প্রদান করুন। হে আল্লাহ, যে সকল আহল কিতাব আপনার পথ থেকে মানুষদেরকে বাধা দেয়, আপনার রাসূলগণকে অবিশ্বাস করে এবং আপনার ওলীগণের সাথে যুদ্ধ করে তাদের অভিশপ্ত করুন, তাদের মধ্যে অনৈক্য সৃষ্টি করুন, তাদের পদসমূহ কম্পমান করুন, তাদের উপর আপনার শাস্তি নাযিল করুন, যে শাস্তি অপ্রতিরোধ্যভাবে পাপাচারী সম্প্রদায়কে পাকড়াও করে।" + "', bnTransliteration = '" + "বিসমিল্লা-হির রা‘হ্মা-নির রা‘হীম। আল্লা-হুম্মা, ইন্না- নাস্তা‘য়ীনুকা, ওয়া নাস্তাগ্ফিরুকা, ওয়া নুস্নী ‘আলাইকা, ওয়া নাশ্কুরুকা ওয়ালা- নাক্ফুরুকা, ওয়া নাখলা‘উ ওয়া নাতরুকু মান ইয়াফজুরুকা। আল্লা-হুম্মা ইয়্ইয়াকা- না’বুদু, ওয়া লাকা নুস্বাল্লী ওয়া নাস্জুদু, ওয়া লাকা নাস্‘আ- ওয়া না‘হফিদু, নাখ্শা ‘আযা-বাকাল জিদ্দা, ওয়া নারজূ রা‘হমাতাকা, ইন্না ‘আযাবাকা বিল কাফিরীনা মুল‘িহক্ক।” আল্লা-হুম্মাগ্ফির লানা- ওয়ালিল মু’মিনীনা ওয়াল মু’মিনা-তি, ওয়াল মুসলিমীনা ওয়াল মুসলিমা-তি, ওয়া আল্লিফ্ বাইনা ক্বুলূবিহিম, ওয়া আস্বলি‘হ যাতা বাইনিহিম, ওয়ানস্বুরহুম ‘আলা ‘আদুওয়িকা ওয়া ‘আদুওয়িহিম। আল্লা-হুম্মাল‘আন কাফারাতা আহলিল কিতাবিল্ লাযীনা ইয়াস্বুদ্দূনা ‘আন সাবীলিকা ওয়া ইউকায্যিবূনা রুসূলাকা ওয়া ইউক্কা-তিলূনা আওলিয়া-য়িকা। আল্লা-হুম্মা, খালিফ বাইনা কালিমাতিহিম, ওয়া যালযিল আক্ক্দামাহুম, ওয়া আনযিল বিহিম বা’সাকাল্ লাযী লা- তারুদ্দুহূ ‘আনিল ক্কাওমিয যালিমীন।" + "', bnReference = '" + "রাহে বেলায়াত - যিকর নং ৮৫" + "' WHERE id = 138")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "কতই না পবিত্র-মহান সেই মহাপবিত্র বাদশা! যিনি ফেরেশতা ও রূহ -এর রব।" + "', bnTransliteration = '" + "সুবহা-নাল মালিকিল ক্বুদ্দূস রাব্বিল মালা-ইকাতি ওয়ার-রূহ" + "', bnReference = '" + "নাসাঈ, ৩/২৪৪, নং ১৭৩৪; দারা কুতনী, ২/৩১ ও অন্যান্যগণ। আর দুই ব্রাকেটের মাঝখানের অংশ দারা কুতনীতে ২/৩১, নং ২ বেশি বর্ণিত। যার সনদ বিশুদ্ধ। আরও দেখুন, শু‘আইব আল-আরনাঊত ও আবদুল কাদের আল-আরনাঊত এর ‘যাদুল মা‘আদ’ গ্রন্থের সম্পাদনা ১/৩৩৭।" + "' WHERE id = 139")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার বান্দা, আপনারই এক বান্দার পুত্র এবং আপনার এক বাঁদীর পুত্র। আমার কপাল (নিয়ন্ত্রণ) আপনার হাতে; আমার উপর আপনার নির্দেশ কার্যকর; আমার ব্যাপারে আপনার ফয়সালা ন্যায়পূর্ণ। আমি আপনার কাছে প্রার্থনা করি আপনার প্রতিটি নামের উসীলায়; যে নাম আপনি নিজের জন্য নিজে রেখেছেন অথবা আপনি আপনার কিতাবে নাযিল করেছেন অথবা আপনার সৃষ্টজীবের কাউকেও শিখিয়েছেন অথবা নিজ গায়েবী জ্ঞানে নিজের জন্য সংরক্ষণ করে রেখেছেন—আপনি কুরআনকে বানিয়ে দিন আমার হৃদয়ের প্রশান্তি, আমার বক্ষের জ্যোতি, আমার দুঃখের অপসারণকারী এবং দুশ্চিন্তা দূরকারী।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী ‘আবদুকা ইবনু ‘আবদিকা ইবনু আমাতিকা, না-সিয়াতী বিয়াদিকা, মা-দ্বিন ফিয়্যা হুকমুকা, ‘আদলুন ফিয়্যা কাদ্বা-য়ুকা, আসআলুকা বিকুল্লি ইসমিন্ হুয়া লাকা সাম্মাইতা বিহি নাফসাকা, আও আনযালতাহু ফী কিতা-বিকা আও ‘আল্লামতাহু আহাদাম্-মিন খালক্বিকা আও ইস্তা’সারতা বিহী ফী ‘ইলমিল গাইবি ‘ইনদাকা, আন্ তাজ‘আলাল কুরআ-না রবী‘আ ক্বালবী, ওয়া নূরা সাদ্‌রী, ওয়া জালা’আ হুযনী ওয়া যাহা-বা হাম্মী" + "', bnReference = '" + "আহমাদ ১/৩৯১, নং ৩৭১২ আর শাইখ আলবানী তাঁর সিলসিলাতুল আহাদীসিস সহীহাহ গ্রন্থে ১/৩৩৭ একে সহীহ বলেছেন।" + "' WHERE id = 140")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! নিশ্চয় আমি আপনার আশ্রয় নিচ্ছি দুশ্চিন্তা ও দুঃখ থেকে, অপারগতা ও অলসতা থেকে, কৃপণতা ও ভীরুতা থেকে, ঋণের ভার ও মানুষদের দমন-পীড়ন থেকে।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নি আ‘ঊযু বিকা মিনাল হাম্মি ওয়াল হাযানি, ওয়াল ‘আজযি ওয়াল কাসালি, ওয়াল বুখলি ওয়াল জুবনি, ওয়া দালা‘ইদ দ্বাইনে ওয়া গালাবাতির রিজা-লি" + "', bnReference = '" + "বুখারী, ৭/১৫৮, নং ২৮৯৩; আরও দেখুন, বুখারী, (ফাতহুল বারীসহ) ১১/১৭৩; আরও দেখুন যা ৪১.২ নং দুআ এ বর্ণিত হবে।" + "' WHERE id = 141")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তিনি মহান ও সহিষ্ণু। ‘আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তিনি মহান আরশের রব্ব। আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তিনি আসমানসমূহের রব্ব, যমীনের রব্ব এবং সম্মানিত আরশের রব্ব।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হুল ‘আযীমূল হালীম। লা ইলা-হা ইল্লাল্লা-হু রব্বুল ‘আরশিল ‘আযীম। লা ইলাহা ইল্লাল্লা-হু রব্বুস সামা-ওয়া-তি ওয়া রব্বুল আরদ্বি ওয়া রব্বুল ‘আরশিল কারীম" + "', bnReference = '" + "[১] বুখারী ৫/২৩৩৬ (ভা ২/৯৩৯); মুসলিম ৪/২০৯২, নং ২৭৩০ (ভা ২/৩৫১)                                                                                 [২] সহীহ। সহীহ ইবনু হিব্বান ৩/১৪৭, মুসনাদ আহমদ ১/৯৪, মাওয়ারিদুয যামআন ৭/৪০৩-৪০৪" + "' WHERE id = 142")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার রহমতেরই আশা করি। তাই আপনি এক নিমেষের জন্যও আমাকে আমার নিজের কাছে সোপর্দ করবেন না। আপনি আমার সার্বিক বিষয়াদি সংশোধন করে দিন। আপনি ছাড়া কোনো হক্ব ইলাহ নেই।" + "', bnTransliteration = '" + "আল্লা-হুম্মা রহ্‌মাতাকা আরজু ফালা তাকিলনী ইলা নাফসী ত্বারফাতা ‘আইন, ওয়া আসলিহ্ লী শা’নি কুল্লাহু, লা ইলা-হা ইল্লা আনতা" + "', bnReference = '" + "আবূ দাউদ, ৪/৩২৪, নং ৫০৯০; আহমাদ ৫/৪২, নং ২০৪৩০। আর শাইখ আলবানী সহীহ আবি দাউদ গ্রন্থে ৩/৯৫৯ এটাকে হাসান হাদীস বলেছেন।" + "' WHERE id = 143")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আপনি ছাড়া কোনো হক্ব ইলাহ নেই, আপনি পবিত্র-মহান, নিশ্চয় আমি যালেমদের অন্তর্ভুক্ত।" + "', bnTransliteration = '" + "লা ইলাহা ইল্লা আনতা সুবহানাকা ইন্নী কুনতু মিনায-যা-লিমীন" + "', bnReference = '" + "সূরা আল আন্মবিয়া - ২১ঃ৮৭" + "' WHERE id = 144")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ! আল্লাহ! (তিনি) আমার রব্ব! আমি তাঁর সাথে কোনো কিছু শরীক করি না।" + "', bnTransliteration = '" + "আল্লাহু আল্লাহু, রব্বী, লা উশরিকু বিহী শাই’আন" + "', bnReference = '" + "[১] হাইসামী, মাওয়ারিদুয যামআন ৭/৪০০-৪০১ [২] ইবনু হাজার আসকালানী, ফাতহুল বারী ১১/১৪৬-১৪৭" + "' WHERE id = 145")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমরা আপনাকে তাদের গলদেশে রাখছি এবং তাদের অনিষ্ট থেকে আপনার নিকট আশ্রয় প্রার্থনা করছি।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্না নাজ্‘আলুকা ফী নুহূরিহিম ওয়া না‘উযু বিকা মিন শুরূরিহিম" + "', bnReference = '" + "আবু দাঊদ ২/৮৯, নং ১৫৩৭; আর হাকেম হাদীসটিকে সহীহ বলেছেন এবং ইমাম যাহাবী একে সমর্থন করেছেন ২/১৪২" + "' WHERE id = 146")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমার শক্তি এবং আপনি আমার সাহায্যকারী; আপনারই সাহায্যে আমি বিচরণ করি, আপনারই সাহায্যে আমি আক্রমন করি এবং আপনারই সাহায্যে আমি যুদ্ধ করি।" + "', bnTransliteration = '" + "আল্লহুম্মা আনতা ‘আদ্বুদী, ওয়া আনতা নাসীরী, বিকা আহূলু, ওয়া বিকা আসূলু, ওয়া বিকা উক্বা-তিলু" + "', bnReference = '" + "আবূ দাউদ ৩/৪২, নং ২৬৩২; তিরমিযী ৫/৫৭২, নং ৩৫৮৪ আরও দেখুন, সহীহুত তিরমিযী, ৩/১৮৩" + "' WHERE id = 147")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক" + "', bnTransliteration = '" + "হাসবুনাল্লা-হু ওয়া নি‘মাল ওয়াকীল" + "', bnReference = '" + "সূরা আল ইমরান - ৩ঃ১৭৩" + "' WHERE id = 148")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, সাত আসমানের রব্ব! মহান আরশের রব্ব! আপনার সৃষ্টিকুলের মধ্য থেকে অমুকের পুত্র অমুকের বিপক্ষে এবং তার বাহিনীর বিরুদ্ধে আপনি আমার আশ্রয়দানকারী হোন; যাতে তাদের কেউ আমার উপর দ্রুত আক্রমণ বা সীমালঙ্ঘন করতে না পারে। আপনার আশ্রিত তো শক্তিশালী, আপনার প্রশংসা তো অতি মহান। আর আপনি ছাড়া কোনো হক্ব ইলাহ নেই।" + "', bnTransliteration = '" + "আল্লা-হুম্মা রব্বাস্ সামা-ওয়া-তিস সাব‘ঈ, ওয়া রব্বাল ‘আরশিল ‘আযীম। কুন লী জারান মিন্ ফুলানিবনি ফুলানিন, ওয়া আহযাবিহী মিন খালা-য়েক্বিকা, আঁই ইয়াফরুত্বা ‘আলাইয়্যা আহাদুম মিনহুম আও ইয়াত্বগা, আয্যা জা-রুকা, ওয়া জাল্লা সানা-উকা, ওয়া লা ইলা-হা ইল্লা আনতা" + "', bnReference = '" + "বুখারী, আল-আদাব আল-মুফরাদ, নং ৭১২ আর শাইখ আলবানী সহীহ আল-আদাবুল মুফরাদ গ্রন্থে, নং ৫৪৫, একে সহীহ বলেছেন।" + "' WHERE id = 149")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ সবচেয়ে বড়, আল্লাহ তাঁর সমস্ত সৃষ্টি থেকে মহামর্যাদাবান। আমি যা থেকে ভীত ও শঙ্কিত তার চেয়ে আল্লাহ মহাপরাক্রমশালী। আমি আল্লাহ্‌র কাছে আশ্রয় চাই, যিনি ছাড়া আর কোনো হক্ব ইলাহ নেই, যিনি সাত আসমানের ধারণকারী, তার অনুমতি ব্যতীত পৃথিবীর উপর পতিত হওয়া থেকে— (আশ্রয় চাই) তাঁর অমুক বান্দা, তার সৈন্য-সামন্ত, তার অনুসারী ও তার অনুগামী জিন ও ইনসানের অনিষ্ট থেকে। হে আল্লাহ! তাদের ক্ষতি থেকে আপনি আমার জন্য আশ্রয়দানকারী হোন। আপনার গুণগান অতি মহান, আপনার আশ্রিত প্রবল শক্তিশালী, আপনার নাম অতি বরকতময়। আর আপনি ছাড়া কোনো হক্ব ইলাহ নেই।" + "', bnTransliteration = '" + "আল্লা-হু আকবার, আল্লা-হু আ‘আয্যু মিন খালক্বিহী জামী‘আন। আল্লাহু আ‘আয্যু মিম্মা আখা-ফু ওয়া আহযারু। আউযু বিল্লা-হিল্লাযী লা ইলা-হা ইল্লা হুওয়াল মুমসিকুস্ সামা-ওয়া-তিস সাব‘ঈ, আন ইয়াকা‘না আলাল্ আরদ্বি ইল্লা বিইযনিহী, মিন শাররি ‘আবদিকা ফুলা-নিন, ওয়া জুনূদিহী ওয়া আতবা‘ইহী ওয়া আশইয়া‘ইহী মিনাল জিন্নি ওয়াল ইনসি। আল্লা-হুম্মা কুন লী জা-রান মিন শাররিহিম, জাল্লা সানা-উকা ওয়া ‘আয্যা জা-রুকা ওয়াতাবা-রকাসমুকা ওয়া লা ইলা-হা গাইরুকা" + "', bnReference = '" + "বুখারী, আল-আদাব আল-মুফরাদ, নং ৭০৮। আর শাইখ আলবানী সহীহ আল-আদাবুল মুফরাদ গ্রন্থে, নং ৫৪৬, একে সহীহ বলেছেন।" + "' WHERE id = 150")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, কিতাব নাযিলকারী, দ্রুত হিসাব গ্রহণকারী! আপনি শত্রুবাহিনীকে পরাভূত করুন। হে আল্লাহ! আপনি তাদেরকে পরাজিত করুন এবং তাদের মধ্যে ত্রাস সৃষ্টি করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা মুনযিলাল কিতা-বি সারী‘আল হিসা-বি ইহযিমিল আহযা-ব। আল্লা-হুম্মাহযিমহুম ওয়া যালযিলহুম" + "', bnReference = '" + "মুসলিম, ৩/১৩৬২, নং ১৭৪২" + "' WHERE id = 151")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি যা ইচ্ছে তা দ্বারাই এদের মোকাবিলায় আমার জন্য যথেষ্ট হোন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাকফিনীহিম বিমা শি’তা" + "', bnReference = '" + "মুসলিম ৪/২৩০০, নং ৩০০৫।" + "' WHERE id = 152")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "কুচিন্তা ও খটকা দূর করতে আল্লাহর নিকট শয়তান থেকে আশ্রয় চাইবে এবং ঐ চিন্তা থেকে নিবৃত্ত হবে।" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বা-নির রাজীম" + "', bnReference = '" + "বুখারী ফাতহুল বারী ৬/৩৩৬, নং ৩২৮৭; মুসলিম ১/১২০, নং ১৩৪" + "' WHERE id = 153")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নিকট আশ্রয় চাই বিতাড়িত শয়তান থেকে। আমি আল্লাহ ও তাঁর রাসূলগণের উপর ঈমান আনলাম। [২]" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লাহি মিনাশ্-শাইত্বা-নির রাজীম আ-মানতু বিল্লা-হি ওয়া রুসুলিহি" + "', bnReference = '" + "[১] বুখারী, (ফাতহুল বারীসহ) ৬/৩৩৬, নং ৩২৭৬; মুসলিম ১/১২০, নং ১৩৪  [২] মুসলিম ১/১১৯-১২০, নং ১৩৪" + "' WHERE id = 154")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "তিনিই সর্বপ্রথম, তিনিই সর্বশেষ, তিনিই সকলের উপরে, তিনিই সকলের নিকটে এবং তিনি সব কিছু সম্পর্কে সর্বজ্ঞ।" + "', bnTransliteration = '" + "হুয়াল আউওয়ালু ওয়াল আ-খিরু ওয়ায্যা-হিরু ওয়াল-বা-ত্বিনু ওয়া হুয়া বিকুল্লি শাই’ইন ‘আলীম" + "', bnReference = '" + "সূরা হাদীদ-৩, আবূ দাউদ ৪/৩২৯, নং ৫১১০। আর শাইখ আলবানী সহীহ আবি দাউদ ৩/৯৬২ একে হাসান বলেছেন।" + "' WHERE id = 155")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমাকে আপনার হালাল দ্বারা পরিতুষ্ট করে আপনার হারাম থেকে ফিরিয়ে রাখুন এবং আপনার অনুগ্রহ দ্বারা আপনি ছাড়া অন্য সকলের থেকে আমাকে অমুখাপেক্ষী করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাকফিনী বিহালা-লিকা ‘আন হারা-মিকা ওয়া আগনিনী বিফাদ্বলিকা ‘আম্মান সিওয়া-ক" + "', bnReference = '" + "তিরমিযী ৫/৫৬০, নং ৩৫৬৩ আরও দেখুন, সহীহুত তিরমিযী, ৩/১৮০।" + "' WHERE id = 156")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! নিশ্চয় আমি আপনার আশ্রয় নিচ্ছি দুশ্চিন্তা ও দুঃখ থেকে, অপারগতা ও অলসতা থেকে, কৃপণতা ও ভীরুতা থেকে, ঋণের ভার ও মানুষদের দমন-পীড়ন থেকে।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী আ‘উযু বিকা মিনাল হাম্মি ওয়াল হাযানি, ওয়া আ‘ঊযু বিকা মিনাল-‘আজযি ওয়াল-কাসালি, ওয়া আ‘ঊযু বিকা মিনাল-বুখলি ওয়াল-জুবনি, ওয়া আ‘ঊযু বিকা মিন দ্বালা‘য়িদ্দাইনি ওয়া গালাবাতির রিজা-ল" + "', bnReference = '" + "বুখারী, ৭/১৫৮, নং ২৮৯৩ তাছাড়া পূর্বে ৩৪.২ নং দুআ এ গত হয়েছে।" + "' WHERE id = 157")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "বিতাড়িত শয়তান থেকে আমি আল্লাহ্‌র আশ্রয় নিচ্ছি।" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বানির রাজীম" + "', bnReference = '" + "মুসলিম ৪/১৭২৯, ২২০৩" + "' WHERE id = 158")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি যা সহজ করেছেন তা ছাড়া কোনো কিছুই সহজ নয়। আর যখন আপনি ইচ্ছা করেন তখন কঠিনকেও সহজ করে দেন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা লা সাহ্‌লা ইল্লা মা জা‘আলতাহু সাহ্‌লান, ওয়া আনতা তাজ্‘আলুল হাযনা ইযা শি’তা সাহ্‌লান" + "', bnReference = '" + "সহীহ ইবন হিব্বান ২৪২৭, (মাওয়ারিদ); ইবনুস সুন্নী, নং ৩৫১ আর হাফেয (ইবন হাজার) বলেন, এটি সহীহ হাদীস। তাছাড়া আবদুল কাদের আরনাউত ইমাম নওয়াবীর আযকার গ্রন্থের তাখরীজে পৃ. ১০৬, একে সহীহ বলে মত প্রকাশ করেছেন।" + "' WHERE id = 159")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "যে কোনো বান্দা কোনো পাপ করার পর উত্তমরূপে ওযু করে দু’ রাক‘আত সালাত আদায় করে আল্লাহর কাছে ক্ষমা চাইলে আল্লাহ তাকে ক্ষমা করে দেন।" + "', bnTransliteration = '" + "মা মিন ‘আবদিন ইউযনিবু যাম্বান ফাইয়ুতত্বাহ্হারু সুম্মা ইউসাল্লী রাক‘আতাইনি সুম্মা ইয়াস্তাগফিরুল্লা-হ" + "', bnReference = '" + "আবু দাউদ ২/৮৬, নং ১৫২১; তিরমিযী ২/২৫৭, নং ৪০৬; সহীহ আবী দাউদ ১/২৮৩" + "' WHERE id = 160")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "শয়তানের খটকা বা কুমন্ত্রণা অনুভব করলে তার অনিষ্ট থেকে আল্লাহর নিকট আশ্রয় প্রার্থনা করবে।" + "', bnTransliteration = '" + "আ‘ঊযু বিল্লা-হি মিনাশ শাইত্বা-নির রাজীম" + "', bnReference = '" + "আবু দাউদ ১/২০৬, নং ৯৮৮, ৯৮৯; সহীহুত তিরমিযী ১/৭৭" + "' WHERE id = 161")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আযান দেওয়া: আযানের শব্দ শুনলে শয়তান বায়ু ত্যাগ করতে করতে পিঠ ফিরিয়ে পলায়ন করে।" + "', bnTransliteration = '" + "আল-আযান" + "', bnReference = '" + "বুখারী ১/১৫১, নং ৬০৮; মুসলিম ১/২৯১, নং ৩৮৯" + "' WHERE id = 162")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "শয়তান তাড়াতে শরী‘আতসম্মত যিক্‌র ও কুরআন তিলাওয়াত করবে, বিশেষ করে সূরা আল-বাক্বারাহ।" + "', bnTransliteration = '" + "আল-আযকারু ওয়া ক্বিরাআতুল কুরআন" + "', bnReference = '" + "মুসলিম ১/৫৩৯, নং ৭৮০; তিরমিযী নং ২৮৭৭" + "' WHERE id = 163")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "এটি আল্লাহ্‌র ফয়সালা, আর তিনি যা ইচ্ছা করেছেন। আল্লাহই আমাদের জন্য যথেষ্ট, আর তিনি কতই না উত্তম কর্মবিধায়ক" + "', bnTransliteration = '" + "কাদারুল্লা-হ, ওয়ামা শা-আ ফা‘আলা হাসবুনাল্লা-হু ওয়া নি‘মাল ওয়াকীল" + "', bnReference = '" + "মুসলিম, ৪/২০৫২, নং ২৬৬৪" + "' WHERE id = 164")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ আপনাকে যা দিয়েছেন তাতে আপনার জন্য বরকত দান করুন, সন্তান দানকারীর শুকরিয়া আদায় করুন, সন্তানটি পরিপূর্ণ বয়সে পদার্পণ করুক এবং তার সদ্ব্যবহার প্রাপ্ত হোন। [১] আল্লাহ আপনাকে বরকত দান করুন, আর আপনার উপর বরকত নাযিল করুন। আল্লাহ আপনাকে উত্তম প্রতিদান দিন, আর আপনাকেও অনুরূপ দান করুন এবং আপনার সওয়াব বহুগুণ বৃদ্ধি করুন। [২]" + "', bnTransliteration = '" + "বা-রাকাল্লা-হু লাকা ফিল মাউহুবি লাক, ওয়া শাকারতাল ওয়া-হিবা, ওয়া বালাগা আশুদ্দাহু, ওয়া রুযিক্তা বিররাহু বা-রাকাল্লা-হু লাকা ওয়া বা-রাকা ‘আলাইকা, ওয়া জাযা-কাল্লা-হু খাইরান, ওয়া রাযাক্বাকাল্লা-হু মিসলাহু ওয়া আজযালা সাওয়া-বাকা" + "', bnReference = '" + "[১] এটি হাসান বসরী রাহিমাহুল্লাহর বাণী হিসেবে উল্লেখিত হয়েছে। দেখুন, তুহফাতুল মাওদূদ লি ইবনিল কাইয়্যেম, পৃ. ২০; তিনি একে ইবনুল মুনযির এর আল-আওসাত্ব গ্রন্থের দিকে সম্পর্কযুক্ত করেছেন।  [২] এটি ইমাম নাওয়াবী তার আল-আযকার গ্রন্থে পৃ. ৩৪৯ উল্লেখ করেছেন। আরও দেখুন, সহীহুল আযকার লিন নাওয়াবী, সলীম আল-হিলালী, ২/৭১[৩] আর এর বিস্তারিত তাখরীজ দেখার জন্য গ্রন্থকারের ‘আয-যিকর ওয়াদ দো‘আ ওয়াল ‘ইলাজ বির রুকা’ গ্রন্থটি দেখুন, পৃ. ১/৪১৬।" + "' WHERE id = 165")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি তোমাদের দু’জনকে আল্লাহ্‌র পরিপূর্ণ কালেমাসমূহের আশ্রয়ে নিচ্ছি যাবতীয় শয়তান ও বিষধর জন্তু থেকে এবং যাবতীয় ক্ষতিকর চক্ষু (বদনযর) থেকে।" + "', bnTransliteration = '" + "উ‘ইযুকুমা বিকালিমা-তিল্লা-হিত তা-ম্মাতি মিন কুল্লি শাইতানিওঁয়া হা-ম্মাহ্‌, ওয়ামিন কুল্লি আইনিল্লা-ম্মাহ্‌" + "', bnReference = '" + "বুখারী ৪/১১৯, নং ৩৩৭১; ইবন আব্বাস রাদিয়াল্লাহু আনহুমার হাদীস থেকে।" + "' WHERE id = 166")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "কোনো ক্ষতি নেই, আল্লাহ যদি চান তো (রোগটি গুনাহ থেকে) পবিত্রকারী হবে।" + "', bnTransliteration = '" + "লা বা’সা তহুরুন ইন শা-আল্লা-হ" + "', bnReference = '" + "বুখারী (ফাতহুল বারীসহ) ১০/১১৮, নং ৩৬১৬।" + "' WHERE id = 167")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি মহান আল্লাহ্‌র কাছে চাচ্ছি, যিনি মহান আরশের রব, তিনি যেন আপনাকে রোগমুক্তি প্রদান করেন।" + "', bnTransliteration = '" + "আসআলুল্লা-হাল ‘আযীম, রব্বাল ‘আরশিল ‘আযীম, আঁই ইয়াশফিয়াকা" + "', bnReference = '" + "[১] তিরমিযী, নং ২০৮৩; আবূ দাউদ, নং ৩১০৬। আরও দেখুন, ২/২১০; সহীহুল জামে‘ ৫/১৮০। [২] তিরমিযী (৮-কিতাবুল জানাইয, ২-ইয়াদাতিল মারীদ) ৩/৩০০ (ভারতীয় ১/১৯১); ইবন মাজাহ (৬-কিতাবুল জানাইয, ২-মান আদা মারীদান) ১/৪৬৩ (ভারতীয় ২/১৫১); মুসতাদরাক হাকিম ১/৫০১" + "' WHERE id = 168")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "রোগী দেখতে গিয়ে তার কাছে বসে সাতবার বলবে: আমি মহান আল্লাহর নিকট প্রার্থনা করছি, যিনি মহা আরশের রব্ব, তিনি যেন আপনাকে আরোগ্য দান করেন।" + "', bnTransliteration = '" + "আসআলুল্লা-হাল ‘আযীমা রব্বাল ‘আরশিল ‘আযীমি আই-ইয়াশফিয়াক" + "', bnReference = '" + "তিরমিযী ও আবু দাউদ; সহীহুত তিরমিযী ২/২১০; সহীহুল জামি‘ ৫/১৮০" + "' WHERE id = 169")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাকে ক্ষমা করুন, আমার প্রতি দয়া করুন এবং আমাকে সর্বোচ্চ বন্ধুর সঙ্গ পাইয়ে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফিরলী ওয়ারহামনী ওয়া আলহিক্বনী বির রফীক্বিল আ‘লা" + "', bnReference = '" + "বুখারী ৭/১০, নং ৪৪৩৫; মুসলিম ৪/১৮৯৩, নং ২৪৪৪" + "' WHERE id = 170")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হ" + "', bnReference = '" + "আবূ দাউদ ৩/১৯০, নং ৩১১৬; আরও দেখুন, সহীহুল জামে‘ ৫/৪৩২" + "' WHERE id = 171")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই, আল্লাহ মহান। একমাত্র আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই। একমাত্র আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই। আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই, যাবতীয় রাজত্ব তাঁরই, তার জন্যই সকল প্রশংসা, আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই, আল্লাহর সাহায্য ছাড়া (পাপ কাজ থেকে দূরে থাকার) কোনো উপায় এবং (সৎকাজ করার) কোনো শক্তি নেই।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হু, আল্লা-হু আকবার, লা ইলা-হা ইল্লাল্লা-হু ওয়াহদাহু, লা ইলা-হা ইল্লাল্লা-হু ওয়াহদাহু লা শারীকা লাহু, লা ইলা-হা ইল্লাল্লা-হু লাহুল মুলকু ওয়ালাহুল হামদু, লা ইলা-হা ইল্লাল্লা-হু ওয়ালা হাউলা ওয়ালা কুওয়াতা ইল্লা বিল্লা-হ" + "', bnReference = '" + "হাদীসটি ইমাম তিরমিযী সংকলন করেছেন, নং ৩৪৩০; ইবন মাজাহ্‌, নং ৩৭৯৪; আর শাইখ আলবানী একে সহীহ বলেছেন। দেখুন, সহীহুত তিরমিযী ৩/১৫২; সহীহ ইবন মাজাহ ২/৩১৭।" + "' WHERE id = 172")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ ব্যতীত কোনো হক্ব ইলাহ নেই, নিশ্চয় মৃত্যুর রয়েছে বিভিন্ন প্রকার ভয়াবহ কষ্ট।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হ, ইন্না লিল মাওতি সাকারা-তিন" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ), ৮/১৪৪, নং ৪৪৪৯; তবে হাদীসে মিসওয়াকের উল্লেখও এসেছে।" + "' WHERE id = 173")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমরা তো আল্লাহ্‌রই। আর নিশ্চয় আমরা তাঁর দিকেই প্রত্যাবর্তনকারী। হে আল্লাহ! আমাকে আমার বিপদে সওয়াব দিন এবং আমার জন্য তার চেয়েও উত্তম কিছু স্থলাভিষিক্ত করে দিন।" + "', bnTransliteration = '" + "ইন্না লিল্লা-হি ওয়া ইন্না ইলাইহি রাজি‘উন। আল্লা-হুম্মা আজুরনী ফী মুসীবাতী ওয়া আখলিফ লী খাইরাম মিনহা" + "', bnReference = '" + "মুসলিম ২/৬৩২, নং ৯১৮।" + "' WHERE id = 174")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি অমুককে (মৃত ব্যক্তির নাম ধরে) ক্ষমা করুন; যারা হেদায়াত লাভ করেছে, তাদের মাঝে তার মর্যাদা উঁচু করে দিন; যারা রয়ে গেছে তাদের মাঝে তার বংশধরদের ক্ষেত্রে আপনি তার প্রতিনিধি হোন। হে সৃষ্টিকুলের রব! আমাদের ও তার গুনাহ মাফ করে দিন। তার জন্য তার কবরকে প্রশস্ত করে দিন এবং তার জন্য তা আলোকময় করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফির লি ফুলা-নিন (মৃতের নাম বলবে) ওয়ারফা‘ দারাজাতাহু ফিল মাহদিয়্যীন, ওয়াখলুফহু ফী ‘আক্বিবিহী ফিল গা-বিরীন, ওয়াগফির লানা ওয়ালাহু ইয়া রব্বাল আ-লামীন। ওয়াফসাহ্‌ লাহু ফী ক্বাবরিহী ওয়া নাউইর লাহু ফী-হি" + "', bnReference = '" + "মুসলিম ২/৬৩৪, নং ৯২০।" + "' WHERE id = 175")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি তাকে ক্ষমা করুন, তাকে দয়া করুন, তাকে পূর্ণ নিরাপত্তায় রাখুন, তাকে মাফ করে দিন, তার মেহমানদারীকে মর্যাদাপূর্ণ করুন, তার প্রবেশস্থান কবরকে প্রশস্ত করে দিন। আর আপনি তাকে ধৌত করুন পানি, বরফ ও শিলা দিয়ে, আপনি তাকে গুনাহ থেকে এমনভাবে পরিষ্কার করুন যেমন সাদা কাপড়কে ময়লা থেকে পরিষ্কার করেছেন। আর তাকে তার ঘরের পরিবর্তে উত্তম ঘর, তার পরিবারের বদলে উত্তম পরিবার ও তার জোড়ের (স্ত্রী/স্বামীর) চেয়ে উত্তম জোড় প্রদান করুন। আর আপনি তাকে জান্নাতে প্রবেশ করান এবং তাকে কবরের আযাব [ও জাহান্নামের আযাব] থেকে রক্ষা করুন" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফির লাহু, ওয়ারহামহু, ওয়া ‘আ-ফিহি, ওয়া‘ফু ‘আনহু, ওয়া আকরিম নুযুলাহু, ওয়াওয়াসসি‘ মুদখালাহু, ওয়াগসিলহু বিলমা-য়ি ওয়াস্‌সালজি ওয়ালবারাদি, ওয়ানাক্বক্বিহি মিনাল খাতা-ইয়া কামা নাক্কাইতাস সাওবাল আবইয়াদা মিনাদদানাসি, ওয়া আবদিলহু দা-রান খাইরাম মিন দা-রিহি, ওয়া আহলান খাইরাম মিন আহলিহি, ওয়া যাওজান খাইরাম মিন যাওজিহি, ওয়া আদখিলহুল জান্নাতা, ওয়া আ‘য়িযহু মিন ‘আযা-বিল ক্বাবরি [ওয়া ‘আযাবিন্না-র]" + "', bnReference = '" + "মুসলিম ২/৬৬৩, নং ৯৬৩" + "' WHERE id = 176")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাদের জীবিত ও মৃত, উপস্থিত ও অনুপস্থিত, ছোট ও বড় এবং নর ও নারীদেরকে ক্ষমা করুন। হে আল্লাহ! আপনি আমাদের মধ্যে যাদের আপনি জীবিত রাখবেন তাদেরকে ইসলামের উপর জীবিত রাখুন এবং যাদেরকে মৃত্যু দান করবেন তাদেরকে ঈমানের সাথে মৃত্যু দান করুন। হে আল্লাহ! আমাদেরকে তার (মৃত্যুতে ধৈয্যধারণের) সওয়াব থেকে বঞ্চিত করবেন না এবং তার (মৃত্যুর) পর আমাদেরকে পথভ্রষ্ট করবেন না।" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফির লিহায়্যিনা ওয়া মায়্যিতিনা ওয়া শা-হিদিনা ওয়া গা-য়িবিনা ওয়া সগীরিনা ওয়া কাবীরিনা ওয়া যাকারিনা ওয়া উনসা-না। আল্লা-হুম্মা মান আহ্ইয়াইতাহু মিন্না ফা’আহয়িহি ‘আলাল-ইসলাম। ওয়ামান তাওয়াফ্‌ফাইতাহু মিন্না ফাতাওয়াফফাহু ‘আলাল ঈমান। আল্লা-হুম্মা লা তাহরিমনা আজরাহু ওয়ালা তুদ্বিল্লান্না বা‘দাহু" + "', bnReference = '" + "আবূ দাঊদ, নং ৩২০১; তিরমিযী, নং ১০২৪; নাসাঈ, নং ১৯৮৫; ইবন মাজাহ, ১/৪৮০, নং ১৪৯৮; আহমাদ ২/৩৬৮, নং ৮৮০৯। আরও দেখুন, সহীহ ইবন মাজাহ্‌ ১/২৫১" + "' WHERE id = 177")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, অমুকের পুত্র অমুক আপনার যিম্মাদারীতে, আপনার প্রতিবেশিত্বের নিরাপত্তায়; সুতরাং আপনি তাকে কবরের পরীক্ষা থেকে এবং জাহান্নামের শাস্তি থেকে রক্ষা করুন। আর আপনি প্রতিশ্রুতি পূর্ণকারী এবং প্রকৃত সত্যের অধিকারী। অতএব, আপনি তাকে ক্ষমা করুন এবং তার উপর দয়া করুন। নিশ্চয় আপনি ক্ষমাশীল, দয়ালু।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্না ফুলানাবনা ফুলা-নিন ফী যিম্মাতিকা, ওয়া হাবলি জিওয়ারিকা, ফাক্বিহি মিন ফিতনাতিল ক্বাবরি ওয়া আযা-বিন না-রি, ওয়া আনতা আহলুল ওয়াফাই ওয়াল হাক্ক, ফাগফির লাহু ওয়ারহামহু, ইন্নাকা আনতাল গাফুরুর রাহীম" + "', bnReference = '" + "ইবন মাজাহ্‌, নং ১৪৯৯। দেখুন, সহীহ ইবন মাজাহ ১/২৫১ তাছাড়া হাদীসটি আবূ দাউদও বর্ণনা করেছেন, ৩/২১১, নং ৩২০২" + "' WHERE id = 178")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, আপনার এক দাস, আর এক দাসীর পুত্র, আপনার অনুগ্রহের মুখাপেক্ষী, আপনি তাকে শাস্তি দেওয়া থেকে অমুখাপেক্ষী। যদি সে নেককার বান্দা হয়, তবে তার সওয়াব আরও বাড়িয়ে দিন, আর যদি বদকার বান্দা হয়, তবে তার অপরাধকর্ম এড়িয়ে যান।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ‘আবদুকা, ওয়াবনু আমাতিকা, ইহতাজা ইলা রাহমাতিকা, ওয়া আনতা গানিয়্যুন ‘আন ‘আযা-বিহি, ইন কা-না মুহসিনান ফাযিদ ফী হাসানা-তিহি, ওয়া ইনকা-না মুসীআন ফা তাজা-ওয়ায ‘আনহু" + "', bnReference = '" + "হাদীসটি সংকলণ করেন, হাকেম তাঁর মুস্তাদরাকে এবং সহীহ বলেছেন, ১/৩৫৯; আর যাহাবী সেটা সমর্থন করেছেন। আরও দেখুন, আলবানী, আহকামুল জানায়েয, পৃ. ১২৫।" + "' WHERE id = 179")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, তাকে তার পিতা-মাতার জন্য অগ্রগামী প্রতিনিধি বা সওয়াব ও সযত্নে গচ্ছিত সওয়াব হিসেবে কবুল করুন। আর তাকে এমন শাফা‘আতকারী বানান, যার শাফা‘আত কবুল হয়। হে আল্লাহ, এ শিশুর দ্বারা তার পিতা মাতার ওজনসমূহ আরও ভারী করে দিন। আর এর দ্বারা তাদের দু’জনের সওয়াব আরও বাড়িয়ে দিন। আর তাকে নেককারদের সঙ্গী-সাথী বানান এবং তাকে ইবরাহীম আলাইহিসসালামের যিম্মায় রাখুন। আর আপনার রহমতের অসীলায় তাকে জাহান্নামের শাস্তি থেকে রক্ষা করুন। তাকে তার এ বাসস্থানের পরিবর্তে উত্তম বাসস্থান প্রদান করুন, এখানকার পরিবার-পরিজনের পরিবর্তে উত্তম পরিবার-পরিজন প্রদান করুন। হে আল্লাহ, আমাদের পূর্ববর্তী নর-নারী ও নাবালক অগ্রগামী সন্তান-সন্ততিদের মাফ করুন এবং যারা ঈমান সহকারে আমাদের পূর্বে মারা গেছে তাদেরকেও।" + "', bnTransliteration = '" + "আল্লা-হুম্মাজ‘আলহু ফারাত্বান ওয়া যুখরান লিওয়লিদায়হি, ওয়াশাফী‘আন মুজাবান। আল্লা-হুম্মা সাক্কিল বিহী মাওয়াযীনাহুমা, ওয়াআ‘যিম বিহী উজূরাহুমা, ওয়া আলহিক্বহু বিসা-লিহিল মু’মিনীন, ওয়াজ‘আলহু ফী কাফা-লাতি ইবরাহীমা, ওয়াক্বিহি বিরাহমাতিকা ‘আযা-বাল জাহীম, ওয়া আবদিলহু দা-রান খাইরান মিন দা-রিহি, ওয়া আহলান খায়রান মিন আহলিহি, আল্লা-হুম্মাগফির লি’আসলাফিনা ওয়া আফরাত্বিনা ওয়া মান সাবাক্বানা বিল ঈমান।" + "', bnReference = '" + "দেখুন, আল-মুগনী, লি ইবন কুদামা, ৩/৪১৬; আরও দেখুন, আদ-দুরুসুল মুহিম্মাহ লি ‘আম্মাতিল উম্মাহ, লিশ শাইখ আবদিল আযীয ইবন আব্দিল্লাহ ইবন বায, রাহেমাহুল্লাহ, পৃ. ১৫।" + "' WHERE id = 180")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, আমাদের জন্য তাকে অগ্রগামী প্রতিনিধি, অগ্রিম পূণ্য এবং সওয়াব হিসেবে নির্ধারণ করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাজ‘আলহু লানা ফারাত্বান ওয়া সালাফান ওয়া আজরান" + "', bnReference = '" + "হাসান বসরী রাহেমাহুল্লাহ যখন ছোট শিশুদের জানাযা পড়তেন তখন তার উপর সূরা ফাতেহা পড়তেন এবং উপরোক্ত দো‘আ বলতেন। হাদীসটি ইমাম বাগভী তার শারহুস সুন্নাহ ৫/৩৫৭ এ বর্ণনা করেছেন। আরও বর্ণনা করেছেন, আব্দুর রায্‌যাক তার মুসান্নাফে, নং ৬৫ ৮৮। তাছাড়া ইমাম বুখারী, কিতাবুল জানায়েয এর, ৬৫, বাবু কিরাআতি ফাতিহাতিল কিতাব আলাল জানাযাত ২/১১৩; ১৩৩৫ নং হাদীসের পূর্বে এটাকে তা‘লীক বা সনদ ব্যতীত বর্ণনা করেছেন।" + "' WHERE id = 181")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নিশ্চয় যা নিয়ে গেছেন আল্লাহ্‌ তা তাঁরই, আর যা কিছু প্রদান করেছেন তাও তাঁর। তাঁর কাছে সব কিছুর একটি নির্দিষ্ট সময় রয়েছে। কাজেই সবর করা এবং সওয়াবের আশা করা উচিত।" + "', bnTransliteration = '" + "ইন্না লিল্লা-হি মা আখাযা, ওয়ালাহু মা আ‘তা, ওয়া কুল্লু শাই’ইন ‘ইনদাহু বিআজালিম মুসাম্মা, ফালতাসবির ওয়াল তাহতাসিব" + "', bnReference = '" + "বুখারী, ২/৮০, নং ১২৮৪; মুসলিম, ২/৬৩৬, নং ৯২৩" + "' WHERE id = 182")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহর নামে এবং রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লামের নিয়মে।" + "', bnTransliteration = '" + "বিসমিল্লা-হি ওয়া আলা সুন্নাতি রাসুলিল্লা-হি" + "', bnReference = '" + "আবূ দাউদ ৩/৩১৪, নং ৩২১৫ সহীহ সনদে; অনুরূপভাবে আহমাদ, নং ৫২৩৪; আর ৪৮১২ এর শব্দ হচ্ছে, ‘বিসমিল্লাহ ওয়া আলা মিল্লাতি রাসূলিল্লাহ’ অর্থাৎ ‘আল্লাহর নামে এবং রাসূলুল্লাহর মিল্লাতের উপর।’ তার সনদও বিশুদ্ধ।" + "' WHERE id = 183")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি তাকে ক্ষমা করুন, হে আল্লাহ্‌ আপনি তাকে (প্রশ্নোত্তরের সময়) স্থির রাখুন।" + "', bnTransliteration = '" + "আল্লা-হুম্মাগফির লাহু, আল্লা-হুম্মা সাববিতহু" + "', bnReference = '" + "আবু দাউদ ৩/৩১৫, নং ৩২২৩; হাকেম এবং তিনি একে সহীহ বলেছেন, আর যাহাবী সমর্থন করেছেন, ১/৩৭০।" + "' WHERE id = 184")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে গৃহসমূহের অধিবাসী মুমিন ও মুসলিমগণ! তোমাদের প্রতি শান্তি বর্ষিত হোক। আর নিশ্চয় আমরা ইনশাআল্লাহ আপনাদের সাথে মিলিত হবো। [আল্লাহ আমাদের পুর্ববর্তীদের এবং পরবর্তীদের প্রতি দয়া করুন।] আমি আল্লাহ্‌র নিকট আমাদের জন্য এবং তোমাদের জন্য নিরাপত্তা প্রার্থনা করি।" + "', bnTransliteration = '" + "আস্‌সালা-মু আলাইকুম আহলাদ্দিয়ারি মিনাল মু’মিনীনা ওয়াল মুসলিমীনা, ওয়াইন্না ইনশা-আল্লা-হু বিকুম লা-হিকুনা, [ওয়া ইয়ারহামুল্লাহুল মুসতাক্বদিমীনা মিন্না ওয়াল মুসতা’খিরীনা], আসআলুল্লাহা লানা ওয়ালাকুমুল ‘আ-ফিয়াহ" + "', bnReference = '" + "মুসলিম ২/৬৭১, নং ৯৭৫; ইবন মাজাহ্‌, ১/৪৯৪, আর শব্দ তাঁরই, নং ১৫৪৭; বুরাইদা রাদিয়াল্লাহু ‘আনহু থেকে। আর দু ব্রাকেটের মাঝখানের অংশ আয়েশা রাদিয়াল্লাহু আনহার হাদীস থেকে, যা সংকলন করেছেন, মুসলিম, ২/৬৭১, নং ৯৭৫।" + "' WHERE id = 185")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমি আপনার নিকট এর কল্যাণ চাই। আর আমি আপনার নিকট এর অনিষ্ট থেকে আশ্রয় চাই।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী আসআলুকা খাইরাহা ওয়া আ‘ঊযু বিকা মিন শাররিহা" + "', bnReference = '" + "আবূ দাউদ ৪/৩২৬, নং ৫০৯৯; ইবন মাজাহ্‌ ২/১২২৮, নং ৩৭২৭। আরও দেখুন, সহীহ ইবন মাজাহ্‌ ২/৩০৫।" + "' WHERE id = 186")
