        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আমাদের পার্শ্ববর্তী এলাকায় (বর্ষণ করুন), আমাদের উপর নয়। হে আল্লাহ! উঁচু ভূমিতে, পাহাড়ে, উপত্যকার কোলে ও বনাঞ্চলে (বর্ষণ করুন)।" + "', bnTransliteration = '" + "আল্লা-হুম্মা হাওয়ালাইনা ওয়ালা ‘আলাইনা। আল্লা-হুম্মা আলাল-আ-কা-মি ওয়ায্যিরা-বি ওয়াবুতূনিল আওদিয়াতি ওয়ামানা-বিতিশ শাজারি" + "', bnReference = '" + "বুখারী ১/২২৪, নং ৯৩৩; মুসলিম ২/৬১৪, নং ৮৯৭।" + "' WHERE id = 194")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ সবচেয়ে বড়। হে আল্লাহ! এই নতুন চাঁদকে আমাদের উপর উদিত করুন নিরাপত্তা, ঈমান, শান্তি ও ইসলামের সাথে; আর হে আমাদের রব্ব! যা আপনি পছন্দ করেন এবং যাতে আপনি সন্তুষ্ট হন তার প্রতি তাওফীক লাভের সাথে। আল্লাহ আমাদের রব্ব এবং তোমার (চাঁদের) রব্ব।" + "', bnTransliteration = '" + "আল্লা-হু আকবার, আল্লা-হুম্মা আহিল্লাহু ‘আলাইনা বিলআমনি ওয়ালঈমানি ওয়াস্‌সালা-মাতি ওয়াল-ইসলা-মি, ওয়াত্তাওফীকি লিমা তুহিব্বু রব্বানা ওয়া তারদ্বা, রব্বুনা ওয়া রব্বুকাল্লাহ" + "', bnReference = '" + "তিরমিযী ৫/৫০৪, নং ৩৪৫১; আদ-দারিমী, শব্দ তাঁরই, ১/৩৩৬। আরও দেখুন, সহীহুত তিরমিযী, ৩/১৫৭।" + "' WHERE id = 195")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "পিপাসা মিটেছে, শিরাগুলো সিক্ত হয়েছে এবং আল্লাহ্‌ চান তো সওয়াব সাব্যস্ত হয়েছে।" + "', bnTransliteration = '" + "যাহাবায-যামাউ ওয়াবতাল্লাতিল ‘উরূকু ওয়া সাবাতাল আজরু ইনশা-আল্লা-হু" + "', bnReference = '" + "হাদীসটি সংকলন করেছেন আবূ দাউদ ২/৩০৬, নং ২৩৫৯ ও অন্যান্য। আরও দেখুন, সহীহুল জামে‘ ৪/২০৯।" + "' WHERE id = 196")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনার যে রহমত সকল কিছু পরিব্যাপ্ত করে রেখেছে তার উসীলায় আবেদন করি, আপনি আমাকে ক্ষমা করুন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ইন্নী আসআলুকা বিরহ্‌মাতিকাল্লাতী ওয়াসি‘আত কুল্লা শাই’ইন আন তাগফিরা লী" + "', bnReference = '" + "হাদীসটি সংকলন করেছেন, ইবন মাজাহ্‌ ১/৫৫৭, নং ১৭৫৩; যা মূলত আবদুল্লাহ ইবন আমর রাদিয়াল্লাহু আনহুমার দো‘আ। আর হাফেয ইবন হাজার তাঁর তাখরীজুল আযকারে এটার সনদকে হাসান বলেছেন। শরহুল আযকার, ৪/৩৪২" + "' WHERE id = 197")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহর নামে। এর শুরু ও শেষ আল্লাহ্‌র নামে।" + "', bnTransliteration = '" + "বিসমিল্লাহ বিস্‌মিল্লাহি ফী আওওয়ালিহী ওয়া আখিরিহী" + "', bnReference = '" + "হাদীসটি সংকলন করেছেন আবূ দাঊদ ৩/৩৪৭, নং ৩৭৬৭; তিরমিযী, ৪/২৮৮, নং ১৮৫৮। আরও দেখুন, সহীহুত তিরমিযী, ২/১৬৭।" + "' WHERE id = 198")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি আমাদেরকে এই খাদ্যে বরকত দিন এবং এর চেয়েও উত্তম খাদ্য আহার করান। হে আল্লাহ! আপনি আমাদেরকে এই খাদ্যে বরকত দিন এবং আমাদেরকে তা থেকে আরও বেশি দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা বারিক লানা ফীহি ওয়া আত‘ইমনা খাইরাম-মিনহু আল্লা-হুম্মা বারিক লানা ফীহি ওয়াযিদনা মিনহু" + "', bnReference = '" + "তিরমিযী ৫/৫০৬, নং ৩৪৫৫। আরও দেখুন, সহীহুত তিরমিযী, ৩/১৫৮।" + "' WHERE id = 199")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "সকল প্রশংসা আল্লাহ্‌র জন্য, যিনি আমাকে এ আহার করালেন এবং এ রিযিক দিলেন যাতে ছিল না আমার পক্ষ থেকে কোনো উপায়, ছিল না কোনো শক্তি-সামর্থ্য।" + "', bnTransliteration = '" + "আলহামদু লিল্লা-হিল্লাযী আত‘আমানী হা-যা ওয়া রাযাকানীহি মিন গাইরি হাউলিম মিন্নী ওয়ালা কুওয়াতিন" + "', bnReference = '" + "হাদীসটি নাসাঈ ব্যতীত সকল সুনান গ্রন্থকারগণ সংকলন করেছেন। আবূ দাউদ, নং ৪০২৫; তিরমিযী, নং ৩৪৫৮; ইবন মাজাহ, নং ৩২৮৫। আরও দেখুন, সহীহুত তিরমিযী ৩/১৫৯।" + "' WHERE id = 200")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহর জন্যই সকল প্রশংসা; এমন প্রশংসা যা অঢেল, পবিত্র ও যাতে রয়েছে বরকত; [যা যথেষ্ট করা হয় নি] , যা বিদায় দিতে পারব না, আর যা থেকে বিমুখ হতে পারব না, হে আমাদের রব্ব!" + "', bnTransliteration = '" + "আলহামদু লিল্লা-হি হামদান কাসীরান তায়্যিবান মুবা-রাকান ফীহি, গাইরা মাকফিয়্যিন ওয়ালা মুয়াদ্দা‘ইন, ওয়ালা মুসতাগনান ‘আনহু রব্বানা" + "', bnReference = '" + "বুখারী ৬/২১৪, হাদীস নং ৫৪৫৮; তিরমিযী, আর শব্দটি তাঁরই, ৫/৫০৭, নং ৩৪৫৬।" + "' WHERE id = 201")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনি তাদেরকে যে রিযিক দান করেছেন তাতে তাদের জন্য বরকত দিন এবং তাদের গুনাহ মাফ করুন, আর তাদের প্রতি দয়া করুন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা বা-রিক লাহুম ফীমা রাযাক্তাহুম ওয়াগফির লাহুম ওয়ারহামহুম" + "', bnReference = '" + "মুসলিম ৩/১৬১৫, নং ২০৪২" + "' WHERE id = 202")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! যে আমাকে আহার করাবে আপনি তাদেরকে আহার করান এবং যে আমাকে পান করাবে আপনি তাদেরকে পান করান।" + "', bnTransliteration = '" + "আল্লা-হুম্মা আত্ব‘ইম মান আত্ব‘আমানী ওয়াসক্বি মান সাক্বা-নী" + "', bnReference = '" + "মুসলিম ৩/১৬২৬, নং ২০৫৫।" + "' WHERE id = 203")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আপনাদের কাছে রোযাদাররা ইফতার করুন, আপনাদের খাবার যেন সৎলোকেরা খায়, আর আপনাদের জন্য ফিরিশতারা ক্ষমা প্রার্থনা করুন।" + "', bnTransliteration = '" + "আফত্বারা ইন্দাকুমুস সা-ইমূন, ওয়া আকালা ত্বা‘আ-মাকুমুল আবরা-রু, ওয়াসাল্লাত আলাইকুমুল মালা-ইকাহ" + "', bnReference = '" + "সুনান আবি দাউদ ৩/৩৬৭, নং ৩৮৫৬; ইবন মাজাহ ১/৫৫৬, নং ১৭৪৭; নাসাঈ, আমালুল ইয়াওমি ওয়াল লাইলাহ, নং ২৯৬-২৯৮। আর সেখানে স্পষ্টভাবে বর্ণিত আছে যে রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম যখন তার পরিবারের কাছে ইফতার করতেন তখন তা বলতেন। আর শাইখ আলবানী তাঁর সহীহ আবি দাউদে একে সহীহ বলেছেন, ২/৭৩০।" + "' WHERE id = 204")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "যখন তোমাদের কাউকে খাবারের দাওয়াত দেওয়া হয়, সে যেন তা গ্রহণ করে। যদি সে সিয়ামাবস্থায় থাকে তবে সে যেন বরকতের দো‘আ করে, আর যদি সিয়ামে না থাকে তবে যেন খায়।" + "', bnTransliteration = '" + "ইযা দু‘ইয়া আহাদুকুম ফালইউজিব, ফাইন্ কা-না সায়িমান ফালইউসাল্লি, ওয়া ইন্ কা-না মুফত্বিরান ফালইয়াত্ব‘আম" + "', bnReference = '" + "মুসলিম ২/১০৫৪, নং ১৪৩১" + "' WHERE id = 205")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নিশ্চয় আমি রোযাদার, নিশ্চয় আমি রোযাদার।" + "', bnTransliteration = '" + "ইন্নি সা‘ইমুন, ইন্নি সা’ইমুন" + "', bnReference = '" + "বুখারী, (ফাতহুল বারীসহ) ৪/১০৩, নং ১৮৯৪; মুসলিম, ২/৮০৬, নং ১১৫১" + "' WHERE id = 206")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, আপনি আমাদের ফল-ফলাদিতে বরকত দিন, আমাদের শহরে বরকত দিন, আমাদের সা‘ তথা বড় পরিমাপক যন্ত্রে বরকত দিন, আমাদের মুদ্দ তথা ছোট পরিমাপক যন্ত্রে বরকত দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা বা-রিক লানা ফী সামারিনা, ওয়াবা-রিক লানা ফী মাদীনাতিনা, ওয়াবা-রিক লানা ফী সা‘ইনা, ওয়াবা-রিক লানা ফী মুদ্দিনা" + "', bnReference = '" + "মুসলিম, ২/১০০০, নং ১৩৭৩" + "' WHERE id = 207")
