        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "সকল প্রশংসা আল্লাহ্‌র আল্লাহ আপনাকে রহমত করুন আল্লাহ আপনাদেরকে সৎপথ প্রদর্শন করুন এবং আপনাদের অবস্থা উন্নত করুন।" + "', bnTransliteration = '" + "আলহামদু লিল্লা-হি ইয়ারহামুকাল্লা-হ ইয়াহ্‌দীকুমুল্লা-হু ওয়া ইউসলিহু বা-লাকুম" + "', bnReference = '" + "বুখারী ৭/১২৫, নং ৫৮৭০।" + "' WHERE id = 209")
