        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "যাঁর জন্য আপনি আমাকে ভালোবেসেছেন, তিনি আপনাকে ভালোবাসুন।" + "', bnTransliteration = '" + "আহাব্বাকাল্লাযী আহ্বাবতানী লাহু" + "', bnReference = '" + "হাদীসটি সংকলন করেছেন, আবু দাঊদ ৪/৩৩৩, নং ৫১২৫। আর শাইখ আলবানী একে সহীহ আবি দাউদে হাসান বলেছেন, ৩/৯৬৫।" + "' WHERE id = 220")
