        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, আমি জ্ঞাতসারে শিরক করা থেকে আপনার আশ্রয় গ্রহণ করছি এবং অজ্ঞাতসারে যা ঘটে তার জন্য আপনার কাছে ক্ষমা চাচ্ছি।" + "', bnTransliteration = '" + "আল্লা-হুম্মা, ইন্নী আ‘ঊযু বিকা আন্ উশ্রিকা বিকা ওয়া আনা আ‘অ্লামু, ওয়া আস্তাগফিরুকা লিমা- লা- আ‘অ্লামু।" + "', bnReference = '" + "বুখা্রী, আল-আদাবুল মুফরাদ, পৃষ্ঠা ২৫০; আলবানী, সহীহুল আদাবিল মুফরাদ ১/২৫৯।" + "' WHERE id = 223")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ আপনাদের মধ্যে বরকত দান করুন” আর তাদের মধ্যেও আল্লাহ বরকত দিন। আর আপনার মধ্যেও আল্লাহ বরকত দিন।" + "', bnTransliteration = '" + "বা-রাকাল্লা-হু ফীকুম ওয়াফীহিম বা-রাকাল্লা-হ ওয়াফীকা বা-রাকাল্লা-হ" + "', bnReference = '" + "হাদীসটি ইবনুস সুন্নী সংকলন করেছেন, পৃ. ১৩৮, নং ২৭৮। আরও দেখুন, ইবনুল কাইয়্যেমের আল-ওয়াবিলুস সাইয়্যেব, পৃ. ৩০৪ তাহকীক, বশীর মুহাম্মাদ উয়ূন।" + "' WHERE id = 224")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! আপনার পক্ষ থেকে অশুভ মঞ্জুর না হলে অশুভ বলে কিছু নেই। আপনার কল্যাণ ছাড়া কোনো কল্যাণ নেই। আর আপনি ছাড়া কোনো হক্ব ইলাহ নেই। [১]" + "', bnTransliteration = '" + "আল্লা-হুম্মা লা ত্বাইরা ইল্লা ত্বাইরুকা ওয়ালা খাইরা ইল্লা খাইরুকা ওয়ালা ইলা-হা গাইরুকা" + "', bnReference = '" + "[১] আহমাদ ২/২২০, নং ৭০৪৫; ইবনুস সুন্নী, হাদীস নং ২৯২ আর শাইখ আলবানী তাঁর সিলসিলাতুল আহাদীসিস সহীহায় ৩/৫৪, নং ১০৬৫, একে সহীহ বলেছেন।  [২] আবু দাউদ, নং ৩৭১৯; আহমাদ, নং ৯০৪০। আর শাইখ আলবানী তাঁর সিলসিলাতুস সহীহায় একে সহীহ বলেছেন, ২/৩৬৩; আবুশ শাইখ, আখলাকুন নবী সাল্লাল্লাহু ‘আলাইহি ওয়াসাল্লাম, পৃ. ২৭০।" + "' WHERE id = 225")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে; আর সকল প্রশংসা আল্লাহ্‌র জন্য। পবিত্র মহান সেই সত্তা, যিনি একে আমাদের জন্য বশীভূত করে দিয়েছেন, অন্যথায় আমরা একে বশীভূত করতে সক্ষম ছিলাম না। আর আমরা অবশ্যই প্রত্যাবর্তন করবো আমাদের রব্বের দিকে। সকল প্রশংসা আল্লাহ্‌র জন্য, সকল প্রশংসা আল্লাহ্‌র জন্য, সকল প্রশংসা আল্লাহ্‌র জন্য। আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়, আল্লাহ সবচেয়ে বড়। হে আল্লাহ! আপনি পবিত্র-মহান; আমি আমার নিজের উপর যুলুম করেছি, সুতরাং আপনি আমাকে মাফ করে দিন। কেননা, আপনি ছাড়া গুনাহ মাফ করার আর কেউ নেই।" + "', bnTransliteration = '" + "বিস্‌মিল্লা-হি, আলহাম্‌দু লিল্লা-হি, সুব্‌হা-নাল্লাযী সাখখারা লানা হা-যা ওয়ামা কুন্না লাহু মুক্বরিনীন। ওয়া ইন্না ইলা রব্বিনা লামুনক্বালিবূন, আলহামদুলিল্লা-হ, আলহামদুলিল্লা-হ, আলহামদুলিল্লা-হ, আল্লা-হু আকবার, আল্লা-হু আকবার, আল্লা-হু আকবার, সুবহা-নাকাল্লা-হুম্মা ইন্নী যালামতু নাফসী ফাগফির লী। ফাইন্নাহু লা ইয়াগফিরুয্যুনূবা ইল্লা আনতা" + "', bnReference = '" + "আবু দাঊদ ৩/৩৪, ২৬০২; তিরমিযী ৫/৫০১, নং ৩৪৪৬। আরও দেখুন, সহীহুত তিরমিযী ৩/১৫৬। আর আয়াত দু’টি হচ্ছে, সূরা আয-যুখরুফের ১৩-১৪" + "' WHERE id = 226")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ সবচেয়ে বড় পবিত্র মহান সেই সত্তা, যিনি আমাদের জন্য একে বশীভূত করে দিয়েছেন, অন্যথায় আমরা একে বশীভূত করতে সক্ষম ছিলাম না। আর আমরা অবশ্যই আমাদের রব্বের নিকট প্রত্যাবর্তন করব। হে আল্লাহ! আমরা এই সফরে আপনার কাছে চাই পূণ্য ও তাকওয়া এবং এমন কাজ যা আপনি পছন্দ করেন। হে আল্লাহ! আমাদের জন্য এই সফরকে সহজ করে দিন এবং এর দুরত্বকে আমাদের জন্য কমিয়ে দিন। হে আল্লাহ্! আপনিই সফরে আমাদের সাথী এবং আমাদের পরিবার-পরিজনের তত্ত্বাবধায়ণকারী। হে আল্লাহ! আমরা আপনার আশ্রয় প্রার্থনা করি সফরের কষ্ট-ক্লেশ থেকে, অবাঞ্ছিত অবস্থার দৃশ্য থেকে এবং সম্পদ ও পরিবারে অনিষ্টকর প্রত্যাবর্তন থেকে। আমরা প্রত্যাবর্তনকারী, তওবাকারী, ইবাদতকারী এবং আমাদের রব্বের প্রশংসাকারী।" + "', bnTransliteration = '" + "আল্লা-হু আকবার সুব্‌হা-নাল্লাযী সাখখারা লানা হা-যা ওয়ামা কুন্না লাহু মুক্বরিনীনা। ওয়া ইন্না ইলা রব্বিনা লামুনক্বালিবূন। আল্লা-হুম্মা ইন্না নাস’আলুকা ফী সাফারিনা হা-যাল-বিররা ওয়াত্তাকওয়া, ওয়ামিনাল ‘আমালি মা তারদ্বা। আল্লা-হুম্মা হাউইন ‘আলাইনা সাফারানা হা-যা ওয়াতউই ‘আন্না বু‘দাহু। আল্লা-হুম্মা আনতাস সা-হিবু ফিস সাফারি ওয়াল-খালীফাতু ফিল আহ্‌লি। আল্লা-হুম্মা ইন্নী আ‘ঊযু বিকা মিন ওয়া‘আসা-ইস্ সাফারি ওয়া কা’আবাতিল মানযারি ওয়া সূ-ইল মুনক্বালাবি ফিল মা-লি ওয়াল আহল আ-ইবূনা তা-ইবূনা ‘আ-বিদূনা, লিরব্বিনা হা-মিদূন" + "', bnReference = '" + "মুসলিম ২/৯৭৮, হাদীস নং ১৩৪২" + "' WHERE id = 227")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! সাত আসমান এবং তা যা কিছু ছায়া দিয়ে রেখেছে তার রব্ব! সাত যমীন এবং তা যা ধারণ করে রেখেছে তার রব্ব! শয়তানদের এবং ওদের দ্বারা পথভ্রষ্টদের রব্ব! বাতাসসমূহ এবং তা যা উড়িয়ে নেয় তার রব্ব! আমি আপনার নিকট চাই এ জনপদের কল্যাণ, এ জনপদবাসীর কল্যাণ এবং এর মাঝে যা আছে তার কল্যাণ। আর আমি আপনার নিকট আশ্রয় চাই এ জনপদের অনিষ্ট থেকে, তাতে বসবাসকারীদের অনিষ্ট থেকে এবং এর মাঝে যা আছে তার অনিষ্ট থেকে।" + "', bnTransliteration = '" + "আল্লা-হুম্মা রব্বাস্ সামা-ওয়া-তিস্ সাব‘ঈ ওয়ামা আযলালনা, ওয়ারব্বাল আরাদীনাস সাব‘ঈ ওয়ামা আক্বলালনা, ওয়া রব্বাশ শাইয়া-তী-নি ওয়ামা আদ্বলালনা, ওয়া রব্বাররিয়া-হি ওয়ামা যারাইনা, আস’আলুকা খাইরা হা-যিহিল কারইয়াতি ওয়া খাইরা আহলিহা ওয়া খাইরা মা ফীহা। ওয়া আ‘ঊযু বিকা মিন শাররিহা ওয়া শাররি আহলিহা ওয়া শাররি মা ফীহা" + "', bnReference = '" + "হাকেম, আর তিনি একে সহীহ বলেছেন এবং ইমাম যাহাবী সেটা সমর্থন করেছেন ২/১০০; ইবনুস সুন্নী, নং ৫২৪ তাছাড়া হাফেয ইবন হাজার তাঁর তাখরীজুল আযকার ৫/১৫৪, একে হাসান বলেছেন। আল্লামা ইবন বায রাহেমাহুল্লাহ বলেন, ‘হাদীসটি নাসাঈ হাসান সনদে বর্ণনা করেছেন।’ দেখুন, তুহফাতুল আখইয়ার, পৃ. ৩৭।" + "' WHERE id = 228")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নেই কোনো মা’বুদ আল্লাহ ছাড়া, তিনি একক, তাঁর কোনো শরীক নেই। রাজত্ব তাঁরই এবং প্রশংসা তাঁরই। (তিনি জীবন দান করেন এবং মৃত্যু দান করেন। আর তিনি চিরঞ্জীব অমর। তাঁর হাতেই সকল কল্যাণ) এবং তিনি সকল কিছুর উপর ক্ষমতাবান।” অনেক বর্ণনায় শুধুমাত্র প্রথম বাক্যটি (ইউহয়ী ওয়া ইউমীতু) সংযুক্ত করে বলা হয়েছে।" + "', bnTransliteration = '" + "লা- ইলা-হা ইল্লাল্লাহু, ওয়া‘হদাহু লা- শারীকা লাহ, লাহুল মুলক, ওয়া লাহুল হামদ, [ইউ‘হয়ী ওয়া ইউমীতু ওয়া হুআ হাইয়ুন লা ইয়ামু-ত, বিইয়াদিহিল খাইরু] ওয়া হুআ ‘আলা- কুল্লি শাইয়িন কদীর।" + "', bnReference = '" + "রাহে বেলায়াত - যিকর নং ৩" + "' WHERE id = 229")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র নামে।" + "', bnTransliteration = '" + "বিসমিল্লা-হ" + "', bnReference = '" + "আবূ দাউদ, ৪/২৯৬, নং ৪৯৮২ আর শাইখ আলবানী একে সহীহ বলেছেন, সহীহ আবি দাউদে, ৩/৯৪১" + "' WHERE id = 230")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি তোমাদেরকে আল্লাহ্‌র হেফাযতে রেখে যাচ্ছি, যাঁর কাছে রাখা আমানতসমূহ কখনও বিনষ্ট হয় না।" + "', bnTransliteration = '" + "আস্তাউদি‘উ কুমুল্লা-হাল্লাযী লা তাদ্বী‘উ ওয়াদা-ই‘উহু" + "', bnReference = '" + "আহমাদ ২/৪০৩, নং ৯২৩০; ইবন মাজাহ্‌, ২/৯৪৩, নং ২৮২৫। আরও দেখুন, সহীহ ইবন মাজাহ্‌ ২/১৩৩" + "' WHERE id = 231")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি আপনার দীন, আপনার আমানত (পরিবার-পরিজন ও ধন-সম্পদ) এবং আপনার সর্বশেষ আমলকে আল্লাহ্‌র হেফাযতে রাখছি।" + "', bnTransliteration = '" + "আস্তাউদি‘উল্লা-হা দীনাকা ওয়া আমা-নাতাকা ওয়া খাওয়া-তীমা ‘আমালিকা" + "', bnReference = '" + "আহমাদ ২/৭, ৪৫২৪, তিরমিযী ৫/৪৯৯, নং ৩৪৪৩ আর শাইখ আলবানী একে সহীহু সুনানিত তিরমিযীতে ৩/৪১৯ সহীহ হাদীস বলেছেন।" + "' WHERE id = 232")
