        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আল্লাহ্‌র পরিপূর্ণ কালেমাসমূহের ওসিলায় আমি তাঁর নিকট তাঁর সৃষ্টির ক্ষতি থেকে আশ্রয় চাই।" + "', bnTransliteration = '" + "আ‘ঊযু বি কালিমা-তিল্লা-হিত তা-ম্মা-তি মিন শাররি মা খালাক্ব" + "', bnReference = '" + "মুসলিম, ৪/২০৮০, নং ২৭০৯।" + "' WHERE id = 236")
