        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "রাসূলুল্লাহ সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম বলেন: তোমরা ঈমান না আনা পর্যন্ত জান্নাতে প্রবেশ করতে পারবে না, এবং পরস্পরকে ভালো না বাসা পর্যন্ত পূর্ণ ঈমানদার হতে পারবে না। আমি কি তোমাদের এমন কাজের কথা বলব যা করলে পরস্পরে ভালোবাসা সৃষ্টি হবে? তোমরা নিজেদের মাঝে সালামের প্রসার ঘটাও।" + "', bnTransliteration = '" + "লা তাদখুলূনাল জান্নাতা হাত্তা তুমিনূ... আফশুস সালা-মা বাইনাকুম" + "', bnReference = '" + "মুসলিম ১/৭৪, নং ৫৪" + "' WHERE id = 244")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "তিনটি গুণ যার মাঝে একত্রিত হবে সে ঈমানের পূর্ণতা অর্জন করবে: নিজের পক্ষ থেকে সুবিচার করা, বিশ্ববাসীকে সালাম দেওয়া এবং অভাবগ্রস্ত অবস্থায়ও দান করা।" + "', bnTransliteration = '" + "সালা-সুন মান জামা‘আহুন্না ফাক্বাদ জামা‘আল ঈমান" + "', bnReference = '" + "বুখারী ফাতহুল বারী ১/৮২" + "' WHERE id = 245")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "এক ব্যক্তি নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম-কে জিজ্ঞাসা করল: ইসলামের কোন কাজটি সর্বোত্তম? তিনি বললেন: ক্ষুধার্তকে অন্ন দান করা এবং পরিচিত-অপরিচিত সকলকে সালাম দেওয়া।" + "', bnTransliteration = '" + "আইয়্যুল ইসলা-মি খাইর? তুত‘ইমুত ত্বা‘আমা ওয়া তাক্বরাউস সালা-মা ‘আলা মান ‘আরাফতা ওয়ামান লাম তা‘রিফ" + "', bnReference = '" + "বুখারী ফাতহুল বারী ১/৫৫, নং ১২; মুসলিম ১/৬৫, নং ৩৯" + "' WHERE id = 246")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আহলে কিতাব (ইহুদী-খ্রিস্টান) তোমাদের সালাম দিলে তোমরা উত্তরে বলবে: ‘ওয়া আলাইকুম’ (তোমাদের উপরও)।" + "', bnTransliteration = '" + "ওয়া ‘আলাইকুম" + "', bnReference = '" + "বুখারী ফাতহুল বারী ১১/৪২, নং ৬২৫৮; মুসলিম ৪/১৭০৫, নং ২১৬৩" + "' WHERE id = 247")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "যখন তোমরা মোরগের ডাক শুনবে তখন আল্লাহর নিকট তাঁর অনুগ্রহ প্রার্থনা করবে; কারণ সে ফেরেশতা দেখেছে। আর যখন গাধার ডাক শুনবে তখন শয়তান থেকে আশ্রয় চাইবে; কারণ সে শয়তান দেখেছে।" + "', bnTransliteration = '" + "ইযা সামি‘তুম সিয়া-হাদ দিয়াকাতি ফাসআলুল্লা-হা মিন ফাদ্বলিহি" + "', bnReference = '" + "বুখারী ফাতহুল বারী ৬/৩৫০, নং ৩৩০৩; মুসলিম ৪/২০৯২, নং ২৭২৯" + "' WHERE id = 248")
