        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ! যে মুমিনকেই আমি গালি দিয়েছি, তা তার জন্য কিয়ামতের দিন আপনার নৈকট্যের মাধ্যম করে দিন।" + "', bnTransliteration = '" + "আল্লা-হুম্মা ফাআইয়্যূমা মু’মিনিন্ সাবাবতুহু ফাজ্‘আল যা-লিকা লাহু কুরবাতান ইলাইকা ইয়াউমাল ক্বিয়া-মাতি" + "', bnReference = '" + "বুখারী (ফাতহুল বারীসহ) ১১/১৭১, নং ৬৩৬১; মুসলিম ৪/২০০৭, নং ৩৯৬, আর তার শব্দ হচ্ছে, “ফাজ‘আলহা লাহূ যাকাতান ও রাহমাতান”। অর্থাৎ ‘সেটা তার জন্য পবিত্রতা ও রহমত বানিয়ে দিন’।" + "' WHERE id = 250")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "“আমি অমুককে এরূপ মনে করি, আল্লাহই তাকে ভাল জানেন (তিনি তার পরিপূর্ণ হিসেব সংরক্ষক), আল্লাহর উপরে আমি কাউকে ভাল বলছি না। আমি তাকে অমুক অমুক গুণের অধিকারী বলে মনে করি।" + "', bnTransliteration = '" + "" + "', bnReference = '" + "বুখারী (৫৬-কিতাবুশ শাহাদাত, ১৬-বাব ইযা যাক্কা) ২/৯৪৬ (ভারতীয় ১/৩৬৬); মুসলিম (৫৩-কিতাবুয যুহদ, ১৪-বাবুন নাহয়ি আনিল মাদহি) ৪/২২৯৬ (২/৪১৪) ।" + "' WHERE id = 251")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আল্লাহ, তারা যা বলছে তার জন্য আমাকে পাকড়াও করবেন না, তারা (আমার ব্যাপারে) যা জানে না সে ব্যাপারে আমাকে ক্ষমা করুন। (আর তারা যা ধারণা করে তার চাইতেও আমাকে উত্তম বানান)" + "', bnTransliteration = '" + "আল্লা-হুম্মা লা-তু’আ-খিযনী বিমা ইয়াক্বূলূনা, ওয়াগফিরলী মা-লা ইয়া‘লামূনা, (ওয়াজ‘আলনী খাইরাম মিম্মা ইয়াযুন্নূনা)" + "', bnReference = '" + "বুখারী, আল-আদাবুল মুফরাদ, নং ৭৬১ আর শাইখ আলবানী তাঁর সহীহুল আদাবিল মুফরাদ গ্রন্থে নং ৫৮৫, সেটার সনদকে সহীহ বলেছেন। আর দু’ ব্রাকেটের মাঝখানের অংশ বাইহাকীর শু‘আবুল ঈমান গ্রন্থ থেকে নেওয়া হয়েছে, ৪/২২৮, যা অন্য পদ্ধতিতে এসেছে।" + "' WHERE id = 252")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "আমি আপনার দরবারে হাযির, হে আল্লাহ! আমি আপনার দরবারে উপস্থিত। আমি আপনার দরবারে হাযির, আপনার কোনো শরীক নেই, আমি আপনার দরবারে উপস্থিত। নিশ্চয় সকল প্রশংসা ও নেয়ামত আপনার, আর রাজত্বও। আপনার কোনো শরীক নেই।" + "', bnTransliteration = '" + "লাব্বাইকাল্লা-হুম্মা লাব্বাইকা, লাব্বাইকা লা শারীকা লাকা লাব্বাইক। ইন্নাল-হামদা ওয়ান-নি‘মাতা লাকা ওয়াল মুলক, লা শারীকা লাকা" + "', bnReference = '" + "বুখারী ৩/৪০৮, নং ১৫৪৯; মুসলিম ২/৮৪১, নং ১১৮৪" + "' WHERE id = 253")
