        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "হে আমাদের রব্ব! আমাদেরকে দুনিয়াতে কল্যাণ দিন এবং আখেরাতেও কল্যাণ দিন এবং আমাদেরকে আগুনের শাস্তি থেকে রক্ষা করুন।" + "', bnTransliteration = '" + "রব্বানা আ-তিনা ফিদ্দুনিয়া হাসানাতাওঁ ওয়াফিল আ-খিরাতি হাসানাতাওঁ ওয়াকিনা ‘আযা-বান্না-র" + "', bnReference = '" + "আবূ দাউদ ২/১৭৯, নং ১৮৯৪; মুসনাদে আহমাদ ৩/৪১১, নং ১৫৩৯৮; আল-বাগভী ফী শারহিস সুন্নাহ, ৭/১২৮। আর শাইখ আলবানী সহীহ আবি দাউদে ১/৩৫৪ একে সহীহ বলেছেন। আয়াতটি সূরা আল-বাকারাহ্‌র আয়াত নং ২০১" + "' WHERE id = 255")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই; রাজত্ব তাঁরই, সমস্ত প্রশংসাও তাঁর; আর তিনি সকল কিছুর উপর ক্ষমতাবান।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হু ওয়াহদাহু লা শারীকা লাহু, লাহুল মূলকু ওয়া লাহুল হামদু, ওয়া হুয়া ‘আলা কুল্লি শাই’ইন ক্বাদীর" + "', bnReference = '" + "তিরমিযী নং ৩৫৮৫; আর শাইখুল আলবানী সহীহুত তিরমিযীতে হাদীসটিকে হাসান বলেছেন, ৩/১৮৪; অনুরূপভাবে সিলসিলা সহীহায় ৪/৬।" + "' WHERE id = 256")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "একমাত্র আল্লাহ ছাড়া কোনো হক্ব ইলাহ নেই, তাঁর কোনো শরীক নেই; রাজত্ব তাঁরই, সমস্ত প্রশংসাও তাঁর; আর তিনি সকল কিছুর উপর ক্ষমতাবান।" + "', bnTransliteration = '" + "লা ইলা-হা ইল্লাল্লা-হু ওয়াহদাহু লা শারীকা লাহু, লাহুল মূলকু ওয়া লাহুল হামদু, ওয়া হুয়া ‘আলা কুল্লি শাই’ইন ক্বাদীর" + "', bnReference = '" + "তিরমিযী নং ৩৫৮৫; আর শাইখুল আলবানী সহীহুত তিরমিযীতে হাদীসটিকে হাসান বলেছেন, ৩/১৮৪; অনুরূপভাবে সিলসিলা সহীহায় ৪/৬।" + "' WHERE id = 257")
        db.execSQL("UPDATE dua_item SET bnTranslation = '" + "নবী সাল্লাল্লাহু আলাইহি ওয়াসাল্লাম তাঁর কাসওয়া নামক উটনীর পিঠে আরোহণ করে মাশ‘আরুল হারামে আসলেন, অতঃপর কিবলামুখী হয়ে আল্লাহর নিকট দো‘আ করলেন এবং তাকবীর, তাহলীল ও তাওহীদ পাঠ করলেন।" + "', bnTransliteration = '" + "ফাস্তাক্ববালাল ক্বিবলাতা ফাদা‘আহু ওয়া কাব্বারাহু ওয়া হাল্লালাহু ওয়া ওয়াহ্হাদাহু" + "', bnReference = '" + "মুসলিম ২/৮৮৮, নং ১২১৮" + "' WHERE id = 258")
